import chalk from 'chalk';
import { getSession, getSessionMessages, listSessions } from '../db/sessions.js';
import { copyToClipboard } from '../utils/clipboard.js';
import { MAX_MESSAGES_FOR_CONTEXT } from '../utils/config.js';

interface RestoreOptions {
  copy?: boolean;
  format?: 'context' | 'json' | 'markdown';
}

export async function restoreCommand(id: string, options: RestoreOptions): Promise<void> {
  // Support partial ID matching
  let session = getSession(id);

  if (!session) {
    // Try partial match
    const sessions = listSessions();
    const match = sessions.find(s => s.id.startsWith(id));
    if (match) {
      session = match;
    }
  }

  if (!session) {
    console.log(chalk.red(`Session not found: ${id}`));
    console.log(chalk.dim('Run: cmem list to see available sessions'));
    return;
  }

  const messages = getSessionMessages(session.id);
  const format = options.format || 'context';

  let output: string;

  switch (format) {
    case 'json':
      output = formatAsJson(session, messages);
      break;
    case 'markdown':
      output = formatAsMarkdown(session, messages);
      break;
    case 'context':
    default:
      output = formatAsContext(session, messages);
      break;
  }

  if (options.copy) {
    await copyToClipboard(output);
    console.log(chalk.green('Session context copied to clipboard!'));
    console.log(chalk.dim(`Session: ${session.title}`));
    console.log(chalk.dim(`Messages: ${messages.length}`));
  } else {
    console.log(output);
  }
}

function formatAsContext(
  session: { title: string; projectPath: string | null },
  messages: Array<{ role: string; content: string }>
): string {
  const lines: string[] = [];

  lines.push('# Previous Session Context');
  lines.push('');
  lines.push(`**Session:** ${session.title}`);
  if (session.projectPath) {
    lines.push(`**Project:** ${session.projectPath}`);
  }
  lines.push(`**Messages:** ${messages.length} total (showing last ${Math.min(messages.length, MAX_MESSAGES_FOR_CONTEXT)})`);
  lines.push('');
  lines.push('---');
  lines.push('');
  lines.push('## Conversation History');
  lines.push('');

  // Show last N messages
  const recentMessages = messages.slice(-MAX_MESSAGES_FOR_CONTEXT);

  for (const msg of recentMessages) {
    const roleLabel = msg.role === 'user' ? '**User:**' : '**Claude:**';
    lines.push(roleLabel);
    lines.push(msg.content);
    lines.push('');
  }

  lines.push('---');
  lines.push('');
  lines.push('*Continue this conversation in Claude Code*');

  return lines.join('\n');
}

function formatAsMarkdown(
  session: { title: string; projectPath: string | null; summary: string | null },
  messages: Array<{ role: string; content: string; timestamp: string }>
): string {
  const lines: string[] = [];

  lines.push(`# ${session.title}`);
  lines.push('');

  if (session.projectPath) {
    lines.push(`**Project:** ${session.projectPath}`);
    lines.push('');
  }

  if (session.summary) {
    lines.push('## Summary');
    lines.push(session.summary);
    lines.push('');
  }

  lines.push('## Conversation');
  lines.push('');

  for (const msg of messages) {
    lines.push(`### ${msg.role === 'user' ? 'User' : 'Claude'}`);
    lines.push(`*${msg.timestamp}*`);
    lines.push('');
    lines.push(msg.content);
    lines.push('');
  }

  return lines.join('\n');
}

function formatAsJson(
  session: { id: string; title: string; projectPath: string | null; summary: string | null; createdAt: string; updatedAt: string },
  messages: Array<{ role: string; content: string; timestamp: string }>
): string {
  return JSON.stringify(
    {
      session: {
        id: session.id,
        title: session.title,
        projectPath: session.projectPath,
        summary: session.summary,
        createdAt: session.createdAt,
        updatedAt: session.updatedAt,
      },
      messages: messages.map(m => ({
        role: m.role,
        content: m.content,
        timestamp: m.timestamp,
      })),
    },
    null,
    2
  );
}
