/**
 * Express API Server for GUI
 *
 * Serves the React GUI and provides REST API endpoints.
 */

import express from 'express';
import cors from 'cors';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { existsSync } from 'fs';
import { apiRouter } from './routes.js';
import { getDatabase } from '../db/index.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const DEFAULT_PORT = 3848;

export interface ServerOptions {
  port?: number;
  open?: boolean;
}

export async function startServer(options: ServerOptions = {}): Promise<void> {
  const port = options.port ?? DEFAULT_PORT;

  // Initialize database (getDatabase auto-initializes)
  getDatabase();

  const app = express();

  // Middleware
  app.use(cors());
  app.use(express.json());

  // Disable caching for API routes
  app.use('/api', (_req, res, next) => {
    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, private');
    res.set('Pragma', 'no-cache');
    res.set('Expires', '0');
    next();
  });

  // API routes
  app.use('/api', apiRouter);

  // Serve static files from GUI build
  // When compiled, __dirname is dist/, so we go up one level to project root, then into gui/dist
  const guiDistPath = join(__dirname, '../gui/dist');
  if (existsSync(guiDistPath)) {
    app.use(express.static(guiDistPath));

    // SPA fallback - serve index.html for all non-API routes
    app.get('/{*path}', (_req, res) => {
      res.sendFile(join(guiDistPath, 'index.html'));
    });
  } else {
    // No GUI build available
    app.get('/', (_req, res) => {
      res.json({
        message: 'CMEM API Server',
        note: 'GUI not built. Run: cd gui && npm run build',
        endpoints: {
          lessons: '/api/lessons',
          stats: '/api/stats',
          projects: '/api/projects',
        },
      });
    });
  }

  // Start server
  app.listen(port, () => {
    console.log(`CMEM GUI server running at http://localhost:${port}`);

    if (options.open) {
      // Open browser
      const url = `http://localhost:${port}`;
      const openCommand = process.platform === 'darwin'
        ? `open "${url}"`
        : process.platform === 'win32'
          ? `start "" "${url}"`
          : `xdg-open "${url}"`;

      import('child_process').then(({ exec }) => {
        exec(openCommand);
      });
    }
  });
}
