/**
 * Synthesis Queue Processor
 *
 * Processes the synthesis queue to extract lessons from sessions.
 */

import { getSession, getSessionMessages } from '../db/sessions.js';
import {
  getPendingSynthesis,
  markSynthesisProcessing,
  markSynthesisComplete,
  markSynthesisFailed,
  getSynthesisStats,
} from '../db/lessons.js';
import { synthesisEngine } from './SynthesisEngine.js';

export interface ProcessQueueResult {
  processed: number;
  lessonsCreated: number;
  failed: number;
  errors: string[];
}

/**
 * Process pending items in the synthesis queue
 */
export async function processSynthesisQueue(
  limit: number = 5
): Promise<ProcessQueueResult> {
  const result: ProcessQueueResult = {
    processed: 0,
    lessonsCreated: 0,
    failed: 0,
    errors: [],
  };

  const pending = getPendingSynthesis(limit);

  if (pending.length === 0) {
    return result;
  }

  for (const item of pending) {
    try {
      // Mark as processing
      markSynthesisProcessing(item.id);

      // Get session and messages
      const session = getSession(item.sessionId);
      if (!session) {
        markSynthesisFailed(item.id, 'Session not found');
        result.failed++;
        result.errors.push(`Session not found: ${item.sessionId}`);
        continue;
      }

      const messages = getSessionMessages(session.id);
      if (messages.length === 0) {
        markSynthesisFailed(item.id, 'Session has no messages');
        result.failed++;
        continue;
      }

      // Synthesize lessons
      const synthesisResult = await synthesisEngine.synthesize(session, messages);

      if (synthesisResult.errors.length > 0) {
        result.errors.push(...synthesisResult.errors);
      }

      // Mark complete
      markSynthesisComplete(item.id, synthesisResult.lessonsCreated);

      result.processed++;
      result.lessonsCreated += synthesisResult.lessonsCreated;
    } catch (error) {
      markSynthesisFailed(item.id, String(error));
      result.failed++;
      result.errors.push(`Failed to process ${item.sessionId}: ${String(error)}`);
    }
  }

  return result;
}

/**
 * Get current queue status
 */
export function getQueueStatus(): {
  pending: number;
  processing: number;
  completed: number;
  failed: number;
  totalLessonsCreated: number;
} {
  return getSynthesisStats();
}
