import { useState, useEffect, useCallback } from 'react';
import {
  listHumanSessions,
  listHumanSessionsByProject,
  deleteSession as dbDeleteSession,
  getSession,
  getFavoriteSessionIds,
  toggleFavorite as dbToggleFavorite,
  hasFavoriteSessions,
  getProjectOrders,
  updateProjectOrders,
  hasCustomProjectOrder,
} from '../../db/sessions.js';
import { searchSessions } from '../../db/vectors.js';
import { getEmbedding, initializeEmbeddings, isReady } from '../../embeddings/index.js';
import { hasBackup, backupSessionFile } from '../../utils/config.js';
import { existsSync } from 'fs';
import type { Session } from '../../db/sessions.js';

/**
 * Check if a session is recoverable (source file exists OR backup exists)
 */
function isRecoverable(session: Session): boolean {
  if (!session.sourceFile) return false;
  if (existsSync(session.sourceFile)) return true;
  if (hasBackup(session.sourceFile)) return true;
  return false;
}

/**
 * Ensure a session is backed up (backup if source exists but no backup yet)
 */
function ensureBackedUp(session: Session): void {
  if (!session.sourceFile) return;
  if (existsSync(session.sourceFile) && !hasBackup(session.sourceFile)) {
    backupSessionFile(session.sourceFile);
  }
}

export interface SessionWithFavorite extends Session {
  isFavorite: boolean;
}

export interface Project {
  path: string;
  name: string;
  sessionCount: number;
  totalMessages: number;
  lastUpdated: string;
  sortOrder: number | null; // null = auto-sorted, number = manually positioned
}

export interface UseSessionsOptions {
  projectFilter?: string | null;
}

export interface UseSessionsResult {
  sessions: SessionWithFavorite[];
  projects: Project[];
  loading: boolean;
  error: string | null;
  embeddingsReady: boolean;
  projectFilter: string | null;
  setProjectFilter: (filter: string | null) => void;
  refresh: () => void;
  search: (query: string) => Promise<void>;
  clearSearch: () => void;
  deleteSession: (id: string) => void;
  getSessionById: (id: string) => Session | null;
  toggleFavorite: (sessionId: string) => boolean;
  favoriteSessionIds: Set<string>;
  hasFavoriteSessions: boolean;
  moveProject: (fromIndex: number, toIndex: number) => void;
  hasCustomProjectOrder: boolean;
}

export function useSessions(options: UseSessionsOptions = {}): UseSessionsResult {
  const [sessions, setSessions] = useState<SessionWithFavorite[]>([]);
  const [allSessions, setAllSessions] = useState<SessionWithFavorite[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [embeddingsReady, setEmbeddingsReady] = useState(false);
  const [isSearching, setIsSearching] = useState(false);
  const [projectFilter, setProjectFilter] = useState<string | null>(options.projectFilter ?? null);
  const [favoriteSessionIds, setFavoriteSessionIds] = useState<Set<string>>(new Set());
  const [hasFavSessions, setHasFavSessions] = useState(false);
  const [projectOrderMap, setProjectOrderMap] = useState<Map<string, number>>(new Map());
  const [hasCustomOrder, setHasCustomOrder] = useState(false);

  // Smart sort: favorites (by messages) → custom named (by messages) → rest (by messages)
  const smartSort = useCallback((sessionList: Session[], favIds: Set<string>): SessionWithFavorite[] => {
    const withFavorites = sessionList.map(s => ({
      ...s,
      isFavorite: favIds.has(s.id),
    }));
    return withFavorites.sort((a, b) => {
      const aHasCustom = !!a.customTitle;
      const bHasCustom = !!b.customTitle;

      // Determine tier: 0 = favorite, 1 = custom name, 2 = rest
      const aTier = a.isFavorite ? 0 : aHasCustom ? 1 : 2;
      const bTier = b.isFavorite ? 0 : bHasCustom ? 1 : 2;

      // Different tiers: sort by tier
      if (aTier !== bTier) return aTier - bTier;

      // Same tier: sort by message count (most first)
      if (a.messageCount !== b.messageCount) return b.messageCount - a.messageCount;

      // Same message count: sort by most recent
      return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
    });
  }, []);

  const [projects, setProjects] = useState<Project[]>([]);

  // Calculate projects from all sessions
  const calculateProjects = useCallback((sessionList: SessionWithFavorite[], orderMap: Map<string, number>): Project[] => {
    const projectMap = new Map<string, Project>();

    for (const session of sessionList) {
      if (!session.projectPath) continue;

      const existing = projectMap.get(session.projectPath);
      if (existing) {
        existing.sessionCount++;
        existing.totalMessages += session.messageCount;
        if (new Date(session.updatedAt) > new Date(existing.lastUpdated)) {
          existing.lastUpdated = session.updatedAt;
        }
      } else {
        const pathParts = session.projectPath.split('/');
        projectMap.set(session.projectPath, {
          path: session.projectPath,
          name: pathParts[pathParts.length - 1] || session.projectPath,
          sessionCount: 1,
          totalMessages: session.messageCount,
          sortOrder: orderMap.get(session.projectPath) ?? null,
          lastUpdated: session.updatedAt,
        });
      }
    }

    // Sort projects: manually ordered first (by sortOrder), then auto-sorted by messages → last updated
    return Array.from(projectMap.values()).sort((a, b) => {
      // Both have manual order: sort by order
      if (a.sortOrder !== null && b.sortOrder !== null) {
        return a.sortOrder - b.sortOrder;
      }
      // Only one has manual order: manual first
      if (a.sortOrder !== null && b.sortOrder === null) return -1;
      if (a.sortOrder === null && b.sortOrder !== null) return 1;
      // Neither has manual order: sort by messages → last updated
      if (a.totalMessages !== b.totalMessages) return b.totalMessages - a.totalMessages;
      return new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime();
    });
  }, []);

  const loadSessions = useCallback(() => {
    try {
      const loaded = projectFilter
        ? listHumanSessionsByProject(projectFilter)
        : listHumanSessions();

      // Ensure all sessions with source files are backed up
      loaded.forEach(ensureBackedUp);

      // Filter out sessions that are not recoverable (no source file AND no backup)
      const recoverable = loaded.filter(isRecoverable);

      const favIds = getFavoriteSessionIds();
      const orderMap = getProjectOrders();
      setFavoriteSessionIds(favIds);
      setProjectOrderMap(orderMap);
      setHasFavSessions(hasFavoriteSessions());
      setHasCustomOrder(hasCustomProjectOrder());

      const sorted = smartSort(recoverable, favIds);
      setAllSessions(sorted);
      setSessions(sorted);

      // Calculate projects from ALL recoverable sessions (not filtered)
      if (!projectFilter) {
        setProjects(calculateProjects(sorted, orderMap));
      }

      setError(null);
    } catch (err) {
      setError(String(err));
    } finally {
      setLoading(false);
    }
  }, [projectFilter, smartSort, calculateProjects]);

  const initEmbeddings = useCallback(async () => {
    if (isReady()) {
      setEmbeddingsReady(true);
      return;
    }
    try {
      await initializeEmbeddings();
      setEmbeddingsReady(true);
    } catch {
      setEmbeddingsReady(false);
    }
  }, []);

  useEffect(() => {
    loadSessions();
    initEmbeddings();
  }, [loadSessions, initEmbeddings]);

  // Reload when project filter changes
  useEffect(() => {
    loadSessions();
  }, [projectFilter, loadSessions]);

  const search = useCallback(async (query: string) => {
    if (!query.trim()) {
      setSessions(allSessions);
      setIsSearching(false);
      return;
    }

    if (!embeddingsReady) {
      // Fall back to simple text search
      const filtered = allSessions.filter(s =>
        s.title.toLowerCase().includes(query.toLowerCase()) ||
        (s.summary && s.summary.toLowerCase().includes(query.toLowerCase()))
      );
      setSessions(smartSort(filtered, favoriteSessionIds));
      setIsSearching(true);
      return;
    }

    try {
      setLoading(true);
      const queryEmbedding = await getEmbedding(query);
      const results = searchSessions(queryEmbedding, 20);
      setSessions(smartSort(results, favoriteSessionIds));
      setIsSearching(true);
    } catch (err) {
      setError(String(err));
      // Fall back to text search on error
      const filtered = allSessions.filter(s =>
        s.title.toLowerCase().includes(query.toLowerCase()) ||
        (s.summary && s.summary.toLowerCase().includes(query.toLowerCase()))
      );
      setSessions(smartSort(filtered, favoriteSessionIds));
    } finally {
      setLoading(false);
    }
  }, [allSessions, embeddingsReady, favoriteSessionIds, smartSort]);

  const clearSearch = useCallback(() => {
    setSessions(allSessions);
    setIsSearching(false);
  }, [allSessions]);

  const deleteSessionHandler = useCallback((id: string) => {
    const deleted = dbDeleteSession(id);
    if (deleted) {
      setAllSessions(prev => prev.filter(s => s.id !== id));
      setSessions(prev => prev.filter(s => s.id !== id));
    }
  }, []);

  const getSessionById = useCallback((id: string) => {
    return getSession(id);
  }, []);

  const toggleFavoriteHandler = useCallback((sessionId: string): boolean => {
    const isNowFavorite = dbToggleFavorite('session', sessionId);
    // Update local state
    const newFavIds = new Set(favoriteSessionIds);
    if (isNowFavorite) {
      newFavIds.add(sessionId);
    } else {
      newFavIds.delete(sessionId);
    }
    setFavoriteSessionIds(newFavIds);
    setHasFavSessions(newFavIds.size > 0);
    // Re-sort sessions
    setAllSessions(prev => smartSort(prev, newFavIds));
    setSessions(prev => smartSort(prev, newFavIds));
    return isNowFavorite;
  }, [favoriteSessionIds, smartSort]);

  // Move a project from one position to another
  const moveProject = useCallback((fromIndex: number, toIndex: number) => {
    if (fromIndex === toIndex) return;
    if (fromIndex < 0 || toIndex < 0) return;
    if (fromIndex >= projects.length || toIndex >= projects.length) return;

    // Create a new array with the project moved
    const newProjects = [...projects];
    const [movedProject] = newProjects.splice(fromIndex, 1);
    newProjects.splice(toIndex, 0, movedProject);

    // Update sort orders for all projects
    const orders = newProjects.map((project, index) => ({
      path: project.path,
      sortOrder: index,
    }));

    // Persist to database
    updateProjectOrders(orders);

    // Update local state
    const newOrderMap = new Map<string, number>();
    for (const order of orders) {
      newOrderMap.set(order.path, order.sortOrder);
    }
    setProjectOrderMap(newOrderMap);
    setHasCustomOrder(true);

    // Update projects with new sort orders
    setProjects(newProjects.map((p, i) => ({ ...p, sortOrder: i })));
  }, [projects]);

  return {
    sessions,
    projects,
    loading,
    error,
    embeddingsReady,
    projectFilter,
    setProjectFilter,
    refresh: loadSessions,
    search,
    clearSearch,
    deleteSession: deleteSessionHandler,
    getSessionById,
    toggleFavorite: toggleFavoriteHandler,
    favoriteSessionIds,
    hasFavoriteSessions: hasFavSessions,
    moveProject,
    hasCustomProjectOrder: hasCustomOrder,
  };
}
