import React from 'react';
import { Box, Text } from 'ink';
import { formatBytes, type PurgePreview } from '../../db/maintenance.js';

export interface StorageStats {
  dbSize: number;
  backupsSize: number;
  totalSize: number;
  sessionCount: number;
  messageCount: number;
}

export interface PurgeOption {
  days: number;
  preview: PurgePreview;
}

interface StorageScreenProps {
  stats: StorageStats;
  purgeOptions: PurgeOption[];
  selectedOption: number | null;
  mode: 'view' | 'confirm';
}

export const StorageScreen: React.FC<StorageScreenProps> = ({
  stats,
  purgeOptions,
  selectedOption,
  mode,
}) => {
  const selectedPurge = selectedOption !== null ? purgeOptions[selectedOption] : null;

  return (
    <Box flexDirection="column">
      <Box marginBottom={1}>
        <Text bold color="cyan">Storage Management</Text>
      </Box>

      {/* Storage Stats */}
      <Box flexDirection="column" marginBottom={1}>
        <Text bold>Current Storage:</Text>
        <Text>  Database:  {formatBytes(stats.dbSize)}</Text>
        <Text>  Backups:   {formatBytes(stats.backupsSize)}</Text>
        <Text bold>  Total:     {formatBytes(stats.totalSize)}</Text>
        <Text dimColor>  ({stats.sessionCount} sessions, {stats.messageCount} messages)</Text>
      </Box>

      {mode === 'view' ? (
        <>
          {/* Purge Options */}
          <Box flexDirection="column" marginTop={1}>
            <Text bold>Purge Old Sessions:</Text>
            <Text dimColor>  (Deletes both database entries and backup files)</Text>
            <Text dimColor>  (Starred sessions are always preserved)</Text>
          </Box>

          <Box flexDirection="column" marginTop={1}>
            {purgeOptions.map((option, index) => {
              const hasData = option.preview.sessionsToDelete > 0;
              return (
                <Box key={option.days}>
                  <Text color={hasData ? 'yellow' : 'gray'}>
                    [{index + 1}] Older than {option.days} days: {' '}
                  </Text>
                  {hasData ? (
                    <Text>
                      {option.preview.sessionsToDelete} sessions
                      {option.preview.backupFilesToDelete > 0 && (
                        <Text>, {option.preview.backupFilesToDelete} backups</Text>
                      )}
                      <Text dimColor> (~{formatBytes(option.preview.backupBytesToFree)} freed)</Text>
                    </Text>
                  ) : (
                    <Text dimColor>No sessions to purge</Text>
                  )}
                </Box>
              );
            })}
          </Box>

          <Box marginTop={1}>
            <Text dimColor>[1/2/3] Select option  [Esc] Back</Text>
          </Box>
        </>
      ) : (
        /* Confirm mode */
        selectedPurge && (
          <Box flexDirection="column" marginTop={1}>
            <Text color="red" bold>Confirm Purge:</Text>
            <Text>  Period: Older than {selectedPurge.days} days</Text>
            <Text>  Sessions: {selectedPurge.preview.sessionsToDelete}</Text>
            <Text>  Messages: {selectedPurge.preview.messagesInvolved}</Text>
            {selectedPurge.preview.backupFilesToDelete > 0 && (
              <Text>  Backup files: {selectedPurge.preview.backupFilesToDelete}</Text>
            )}
            <Text>  Date range: {selectedPurge.preview.oldestSessionDate} to {selectedPurge.preview.newestSessionDate}</Text>
            <Text>  Space freed: ~{formatBytes(selectedPurge.preview.backupBytesToFree)}</Text>
            <Box marginTop={1}>
              <Text color="red">This cannot be undone. Proceed? [y/n]</Text>
            </Box>
          </Box>
        )
      )}
    </Box>
  );
};
