import chalk from 'chalk';
import { statSync, existsSync } from 'fs';
import { getStats } from '../db/sessions.js';
import { isModelCached } from '../embeddings/index.js';
import { DB_PATH, CMEM_DIR, EMBEDDING_MODEL, MODELS_DIR, BACKUPS_DIR } from '../utils/config.js';
import { formatBytes, formatNumber } from '../utils/format.js';
import { getBackupsDirSize } from '../db/maintenance.js';

export async function statsCommand(): Promise<void> {
  console.log(chalk.cyan('cmem Storage Statistics\n'));

  // Database stats
  const stats = getStats();

  console.log(chalk.white('Database:'));
  console.log(`  Sessions:    ${formatNumber(stats.sessionCount)}`);
  console.log(`  Messages:    ${formatNumber(stats.messageCount)}`);
  console.log(`  Embeddings:  ${formatNumber(stats.embeddingCount)}`);

  // Storage size
  let totalSize = 0;
  if (existsSync(DB_PATH)) {
    const dbStats = statSync(DB_PATH);
    console.log(`  DB Size:     ${formatBytes(dbStats.size)}`);
    totalSize += dbStats.size;
  }

  // Backups size
  const backupsSize = getBackupsDirSize();
  if (backupsSize > 0) {
    console.log(`  Backups:     ${formatBytes(backupsSize)}`);
    totalSize += backupsSize;
  }

  if (totalSize > 0) {
    console.log(`  Total:       ${formatBytes(totalSize)}`);
  }

  console.log(`  Location:    ${CMEM_DIR}`);

  // Embedding model status
  console.log('');
  console.log(chalk.white('Embeddings:'));

  const modelCached = isModelCached();
  if (modelCached) {
    console.log(`  Model:       ${chalk.green(EMBEDDING_MODEL)}`);
    console.log(`  Location:    ${MODELS_DIR}`);
  } else {
    console.log(`  Model:       ${chalk.yellow('Not downloaded')}`);
    console.log(chalk.dim('  Run cmem setup to download the embedding model'));
  }

  // Coverage
  console.log('');
  console.log(chalk.white('Coverage:'));
  const coveragePercent = stats.sessionCount > 0
    ? Math.round((stats.embeddingCount / stats.sessionCount) * 100)
    : 0;
  console.log(`  Semantic:    ${coveragePercent}% of sessions have embeddings`);

  if (coveragePercent < 100 && stats.sessionCount > 0) {
    console.log(chalk.dim('  Run cmem watch to generate missing embeddings'));
  }
}
