async function promptChoice(question: string, options: string[], defaultChoice = 1): Promise<number> {
  const rl = createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  // Print options
  options.forEach((opt, i) => {
    console.log(chalk.dim(`  ${i + 1}) ${opt}`));
  });
  console.log('');

  return new Promise((resolve) => {
    rl.question(chalk.white(`  Choice [${defaultChoice}]: `), (answer) => {
      rl.close();
      const num = parseInt(answer.trim(), 10);
      if (isNaN(num) || num < 1 || num > options.length) {
        resolve(defaultChoice);
      } else {
        resolve(num);
      }
    });
  });
}

async function promptYesNo(question: string, defaultYes = true): Promise<boolean> {
  const rl = createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  const hint = defaultYes ? '[Y/n]' : '[y/N]';

  return new Promise((resolve) => {
    rl.question(chalk.white(`  ${question} ${chalk.dim(hint)} `), (answer) => {
      rl.close();
      const normalized = answer.toLowerCase().trim();
      if (normalized === '') {
        resolve(defaultYes);
      } else {
        resolve(normalized === 'y' || normalized === 'yes');
      }
    });
  });
}

function isRunningViaNpx(): boolean {
  const execPath = process.argv[1] || '';
  return execPath.includes('_npx') || execPath.includes('.npm/_cacache');
}

function isGloballyInstalled(): boolean {
  try {
    const result = execSync('which cmem 2>/dev/null || where cmem 2>/dev/null', {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim();
    return result.length > 0 && !result.includes('_npx');
  } catch {
    return false;
  }
}

function getCmemVersion(): string {
  try {
    // From dist/cli.js, package.json is one level up
    const packagePath = join(__dirname, '..', 'package.json');
    if (existsSync(packagePath)) {
      const pkg = JSON.parse(readFileSync(packagePath, 'utf-8'));
      return pkg.version || '0.1.0';
    }
  } catch {
    // Ignore
  }
  return '0.1.0';
}

function getInstalledVersion(): string | null {
  try {
    const result = execSync('cmem --version 2>/dev/null', {
      encoding: 'utf-8',
    }).trim();
    return result;
  } catch {
    return null;
  }
}

/**
 * Get the path to the cmem dist directory
 * Works whether running from npx, global install, or local dev
 */
function getCmemDistPath(): string | null {
  try {
    // First, try to find globally installed cmem
    const globalPath = execSync('npm root -g 2>/dev/null', {
      encoding: 'utf-8',
    }).trim();

    const cmemGlobalPath = join(globalPath, '@colbymchenry', 'cmem', 'dist');
    if (existsSync(cmemGlobalPath)) {
      return cmemGlobalPath;
    }

    // Fallback: use the current running script's location
    // __dirname points to dist/commands when running
    const parentDist = dirname(__dirname);
    if (existsSync(join(parentDist, 'hooks'))) {
      return parentDist;
    }

    return null;
  } catch {
    // Fallback to script location
    const parentDist = dirname(__dirname);
    if (existsSync(parentDist)) {
      return parentDist;
    }
    return null;
  }
}

/**
 * Stop and remove old daemon if it exists (from versions < 0.5.0)
 * cmem now uses hooks instead of a background daemon
 */
function cleanupOldDaemon(): void {
  const plistPath = join(homedir(), 'Library', 'LaunchAgents', 'com.cmem.watch.plist');

  if (existsSync(plistPath)) {
    try {
      // Stop the daemon if running
      execSync(`launchctl unload "${plistPath}" 2>/dev/null`, { stdio: 'pipe' });
    } catch {
      // Ignore if not loaded
    }

    try {
      // Remove the plist file
      const { unlinkSync } = require('fs');
      unlinkSync(plistPath);
    } catch {
      // Ignore if can't remove
    }
  }
}

export async function setupCommand(): Promise<void> {
  const currentVersion = getCmemVersion();
  const installedVersion = getInstalledVersion();
  const isGlobal = isGloballyInstalled();
  const isNpx = isRunningViaNpx();

  // Print beautiful banner
  printBanner(currentVersion);

  // Clean up old daemon from previous versions (< 0.5.0)
  // cmem now uses hooks instead of a background daemon
  cleanupOldDaemon();

  // Step 1: Global installation
  if (!isGlobal || isNpx) {
    console.log(chalk.yellow('  Install cmem globally?'));
    console.log(chalk.dim('  Makes the `cmem` command available everywhere\n'));

    const choice = await promptChoice('', [
      'Yes - install globally via npm',
      'No - I\'ll use npx each time',
    ], 1);

    if (choice === 1) {
      console.log(chalk.dim('\n  Installing @colbymchenry/cmem globally...\n'));
      try {
        execSync('npm install -g @colbymchenry/cmem', { stdio: 'inherit' });
        console.log(chalk.green('\n  ✓ Installed globally\n'));
      } catch {
        console.log(chalk.red('\n  ✗ Failed to install. Try: sudo npm install -g @colbymchenry/cmem\n'));
      }
    } else {
      console.log(chalk.dim('\n  Skipped. Use `npx @colbymchenry/cmem` to run.\n'));
    }
  } else if (installedVersion && installedVersion !== currentVersion) {
    console.log(chalk.yellow(`  Update available: ${installedVersion} → ${currentVersion}`));

    const shouldUpdate = await promptYesNo('Update to latest version?');

    if (shouldUpdate) {
      console.log(chalk.dim('\n  Updating @colbymchenry/cmem...\n'));
      try {
        execSync('npm install -g @colbymchenry/cmem', { stdio: 'inherit' });
        console.log(chalk.green('\n  ✓ Updated\n'));
      } catch {
        console.log(chalk.red('\n  ✗ Failed to update\n'));
      }
    } else {
      console.log('');
    }
  } else {
    console.log(chalk.green('  ✓ cmem is installed globally\n'));
  }

  // Step 2: Download embedding model for semantic search
  console.log(chalk.yellow('  Semantic search setup'));
  console.log(chalk.dim('  Enables searching conversations by meaning\n'));

  const modelSpinner = new Spinner('Checking embedding model...');
  modelSpinner.start();

  const cached = isModelCached();

  if (cached) {
    modelSpinner.succeed('Embedding model ready');
  } else {
    modelSpinner.update('Downloading embedding model (~130MB)...');

    try {
      await initializeEmbeddings((progress: InitProgress) => {
        if (progress.status === 'downloading' && progress.progress !== undefined) {
          const percent = Math.round(progress.progress);
          const fileName = progress.file ? progress.file.split('/').pop() : '';
          modelSpinner.update(`Downloading ${fileName}... ${percent}%`);
        } else if (progress.status === 'loading') {
          modelSpinner.update('Loading model...');
        }
      });
      modelSpinner.succeed('Embedding model ready');
    } catch (err) {
      modelSpinner.fail('Failed to download embedding model');
      console.log(chalk.dim(`  Error: ${err}\n`));
    }
  }

  console.log('');

  // Step 3: Claude Code MCP integration
  const mcpConfigured = isMcpConfigured();

  if (mcpConfigured) {
    console.log(chalk.green('  ✓ MCP server configured in Claude Code\n'));
  } else {
    console.log(chalk.yellow('  Add MCP server to Claude Code?'));
    console.log(chalk.dim('  Lets Claude search your past conversations\n'));

    const choice = await promptChoice('', [
      'Yes - configure automatically (recommended)',
      'No - I\'ll configure it manually',
    ], 1);

    if (choice === 1) {
      const success = configureMcpServer();
      if (success) {
        console.log(chalk.green('\n  ✓ Added MCP server to ~/.claude.json'));
        console.log(chalk.green('  ✓ Added permissions to ~/.claude/settings.json'));
        console.log(chalk.dim('  Restart Claude Code or run /mcp to connect\n'));
      } else {
        console.log(chalk.red('\n  ✗ Failed to configure MCP server\n'));
      }
    } else {
      console.log(chalk.dim('\n  Skipped.\n'));
    }
  }

  // Step 4: Configure hooks for automatic learning
  const hooksConfigured = areHooksConfigured();

  if (hooksConfigured) {
    console.log(chalk.green('  ✓ Learning hooks configured\n'));
  } else {
    console.log(chalk.yellow('  Enable automatic learning?'));
    console.log(chalk.dim('  Hooks sync sessions and inject knowledge automatically\n'));

    const choice = await promptChoice('', [
      'Yes - enable hooks (recommended)',
      'No - I\'ll manage manually',
    ], 1);

    if (choice === 1) {
      const result = configureHooks();
      if (result.success) {
        console.log(chalk.green('\n  ✓ Configured hooks in ~/.claude/settings.json'));
        console.log(chalk.dim('  • UserPromptSubmit: Injects relevant lessons'));
        console.log(chalk.dim('  • Stop/PreCompact: Syncs and backs up sessions\n'));
      } else {
        console.log(chalk.red(`\n  ✗ Failed to configure hooks: ${result.message}`));
        console.log(chalk.dim('  You can configure hooks manually in ~/.claude/settings.json\n'));
      }
    } else {
      console.log(chalk.dim('\n  Skipped. Run `cmem watch` for manual sync.\n'));
    }
  }

  // Step 5: Index existing sessions
  console.log(chalk.yellow('  Initial session indexing'));
  console.log(chalk.dim('  Scanning and indexing your existing Claude Code conversations\n'));

  await indexExistingSessions();

  // Mark setup as complete
  if (!existsSync(CMEM_DIR)) {
    mkdirSync(CMEM_DIR, { recursive: true });
  }
  writeFileSync(SETUP_MARKER, new Date().toISOString());

  // Done - show summary
  console.log(chalk.magenta('  ════════════════════════════════════════════'));
  console.log(chalk.green.bold('\n  ✓ Setup complete!\n'));

  console.log(chalk.white('  Commands:'));
  console.log(chalk.dim('    cmem              Browse sessions (TUI)'));
  console.log(chalk.dim('    cmem search "X"   Semantic search'));
  console.log(chalk.dim('    cmem synthesize   Extract lessons from sessions'));
  console.log(chalk.dim('    cmem stats        Storage statistics'));
  console.log(chalk.dim('    cmem --help       All commands'));

  console.log(chalk.white('\n  MCP Tools (available to Claude):'));
  console.log(chalk.dim('    search_sessions   Find past conversations'));
  console.log(chalk.dim('    search_lessons    Find project knowledge'));
  console.log(chalk.dim('    save_lesson       Save important insights'));

  // Check if hooks are configured
  if (areHooksConfigured()) {
    console.log(chalk.green('\n  🧠 Learning is enabled!'));
    console.log(chalk.dim('    • Lessons are injected before each prompt'));
    console.log(chalk.dim('    • Sessions sync automatically on stop/compact'));
    console.log(chalk.dim('    • Run `cmem synthesize` to extract lessons'));
  }

  console.log('');
}

function isMcpConfigured(): boolean {
  // Check if MCP server exists in ~/.claude.json
  if (!existsSync(CLAUDE_JSON_PATH)) {
    return false;
  }

  try {
    const config: ClaudeJson = JSON.parse(readFileSync(CLAUDE_JSON_PATH, 'utf-8'));
    return !!config.mcpServers?.cmem;
  } catch {
    return false;
  }
}

function configureMcpServer(): boolean {
  try {
    // Step 1: Add MCP server to ~/.claude.json
    let claudeJson: ClaudeJson = {};
    if (existsSync(CLAUDE_JSON_PATH)) {
      try {
        claudeJson = JSON.parse(readFileSync(CLAUDE_JSON_PATH, 'utf-8'));
      } catch {
        claudeJson = {};
      }
    }

    if (!claudeJson.mcpServers) {
      claudeJson.mcpServers = {};
    }

    claudeJson.mcpServers.cmem = {
      type: 'stdio',
      command: 'cmem',
      args: ['mcp'],
    };

    writeFileSync(CLAUDE_JSON_PATH, JSON.stringify(claudeJson, null, 2) + '\n');

    // Step 2: Add permissions and hooks to ~/.claude/settings.json
    const claudeDir = dirname(CLAUDE_SETTINGS_PATH);
    if (!existsSync(claudeDir)) {
      mkdirSync(claudeDir, { recursive: true });
    }

    let settings: ClaudeSettings = {};
    if (existsSync(CLAUDE_SETTINGS_PATH)) {
      try {
        settings = JSON.parse(readFileSync(CLAUDE_SETTINGS_PATH, 'utf-8'));
      } catch {
        settings = {};
      }
    }

    if (!settings.permissions) {
      settings.permissions = {};
    }
    if (!settings.permissions.allow) {
      settings.permissions.allow = [];
    }

    // Add any missing cmem permissions
    for (const perm of CMEM_PERMISSIONS) {
      if (!settings.permissions.allow.includes(perm)) {
        settings.permissions.allow.push(perm);
      }
    }

    writeFileSync(CLAUDE_SETTINGS_PATH, JSON.stringify(settings, null, 2) + '\n');

    return true;
  } catch (err) {
    console.error(chalk.red('Error configuring MCP:'), err);
    return false;
  }
}

/**
 * Configure hooks in Claude Code settings
 */
function configureHooks(): { success: boolean; message: string } {
  try {
    const distPath = getCmemDistPath();
    if (!distPath) {
      return { success: false, message: 'Could not find cmem installation path' };
    }

    const consultPath = join(distPath, 'hooks', 'consult.js');
    const syncPath = join(distPath, 'hooks', 'sync.js');

    // Verify hook files exist
    if (!existsSync(consultPath)) {
      return { success: false, message: `Hook file not found: ${consultPath}` };
    }

    // Read current settings
    const claudeDir = dirname(CLAUDE_SETTINGS_PATH);
    if (!existsSync(claudeDir)) {
      mkdirSync(claudeDir, { recursive: true });
    }

    let settings: ClaudeSettings = {};
    if (existsSync(CLAUDE_SETTINGS_PATH)) {
      try {
        settings = JSON.parse(readFileSync(CLAUDE_SETTINGS_PATH, 'utf-8'));
      } catch {
        settings = {};
      }
    }

    // Initialize hooks if not present
    if (!settings.hooks) {
      settings.hooks = {};
    }

    // Helper to check if cmem hook already exists
    const hasCmemHook = (hookArray: HookMatcher[] | undefined): boolean => {
      if (!hookArray) return false;
      return hookArray.some(h => h.hooks?.some(hk => hk.command?.includes('cmem')));
    };

    // Add UserPromptSubmit hook (for lesson injection)
    if (!hasCmemHook(settings.hooks.UserPromptSubmit)) {
      if (!settings.hooks.UserPromptSubmit) {
        settings.hooks.UserPromptSubmit = [];
      }
      settings.hooks.UserPromptSubmit.push({
        matcher: '.*',
        hooks: [{
          type: 'command',
          command: `node "${consultPath}"`,
          timeout: 5000,
        }],
      });
    }

    // Add Stop hook (for session sync)
    if (!hasCmemHook(settings.hooks.Stop)) {
      if (!settings.hooks.Stop) {
        settings.hooks.Stop = [];
      }
      settings.hooks.Stop.push({
        matcher: '.*',
        hooks: [{
          type: 'command',
          command: `node "${syncPath}"`,
        }],
      });
    }

    // Add PreCompact hook (for session sync before compaction)
    if (!hasCmemHook(settings.hooks.PreCompact)) {
      if (!settings.hooks.PreCompact) {
        settings.hooks.PreCompact = [];
      }
      settings.hooks.PreCompact.push({
        matcher: '.*',
        hooks: [{
          type: 'command',
          command: `node "${syncPath}"`,
        }],
      });
    }

    writeFileSync(CLAUDE_SETTINGS_PATH, JSON.stringify(settings, null, 2) + '\n');

    return { success: true, message: 'Hooks configured successfully' };
  } catch (err) {
    return { success: false, message: String(err) };
  }
}

/**
 * Check if hooks are already configured
 */
function areHooksConfigured(): boolean {
  if (!existsSync(CLAUDE_SETTINGS_PATH)) {
    return false;
  }

  try {
    const settings: ClaudeSettings = JSON.parse(readFileSync(CLAUDE_SETTINGS_PATH, 'utf-8'));
    const hooks = settings.hooks;
    if (!hooks) return false;

    // Check if cmem hooks exist
    const hasCmemHook = (hookArray: HookMatcher[] | undefined): boolean => {
      if (!hookArray) return false;
      return hookArray.some(h => h.hooks?.some(hk => hk.command?.includes('cmem')));
    };

    return hasCmemHook(hooks.UserPromptSubmit) || hasCmemHook(hooks.Stop);
  } catch {
    return false;
  }
}

export function shouldRunSetup(): boolean {
  const isNpx = isRunningViaNpx();
  const setupComplete = existsSync(SETUP_MARKER);
  const isGlobal = isGloballyInstalled();

  // Always run setup when invoked via npx
  if (isNpx) return true;

  // Run setup if not installed globally and setup hasn't been completed
  if (!isGlobal && !setupComplete) return true;

  // Check for version mismatch (update available)
  const currentVersion = getCmemVersion();
  const installedVersion = getInstalledVersion();
  if (installedVersion && installedVersion !== currentVersion) {
    return true;
  }

  return false;
}

/**
 * Find all .jsonl session files in the Claude directory
 */
function findAllSessionFiles(dir: string): string[] {
  const files: string[] = [];

  if (!existsSync(dir)) return files;

  function scanDir(currentDir: string, depth: number = 0): void {
    if (depth > 10) return;

    try {
      const entries = readdirSync(currentDir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = join(currentDir, entry.name);

        if (entry.isDirectory()) {
          if (entry.name === 'subagents') continue;
          scanDir(fullPath, depth + 1);
        } else if (entry.isFile() && entry.name.endsWith('.jsonl')) {
          files.push(fullPath);
        }
      }
    } catch {
      // Ignore permission errors
    }
  }

  scanDir(dir);
  return files;
}

/**
 * Index a single session file
 */
async function indexSessionFile(filePath: string, embeddingsReady: boolean): Promise<boolean> {
  try {
    const messages = parseSessionFile(filePath);
    if (messages.length === 0) return false;

    // Check if already indexed
    const existing = getSessionBySourceFile(filePath);
    if (existing) return false;

    // Get file stats
    const stats = statSync(filePath);
    const fileMtime = stats.mtime.toISOString();

    // Generate title and summary
    const firstUserMsg = messages.find(m => m.role === 'user');
    const title = firstUserMsg ? generateTitle(firstUserMsg.content) : 'Untitled Session';
    const summary = generateSummary(messages);

    // Build raw data
    const rawData = JSON.stringify({ filePath, messages, mtime: fileMtime });
    const sessionId_from_file = basename(filePath, '.jsonl');

    // Create session
    const sessionId = createSession({
      title,
      summary,
      projectPath: null,
      sourceFile: filePath,
      rawData,
      messages,
    });

    // Generate embedding if ready
    if (embeddingsReady) {
      const contentLength = messages.reduce((sum, m) => sum + m.content.length, 0);
      const shouldEmbed = needsReembedding(sessionId, contentLength, 500);

      if (shouldEmbed) {
        try {
          const embeddingText = createEmbeddingText(title, summary, messages);
          const embedding = await getEmbedding(embeddingText);
          storeEmbedding(sessionId, embedding);
          updateEmbeddingState(sessionId, contentLength, fileMtime);
        } catch {
          // Ignore embedding errors
        }
      }
    }

    return true;
  } catch {
    return false;
  }
}

/**
 * Index all existing Claude Code sessions
 */
async function indexExistingSessions(): Promise<void> {
  const spinner = new Spinner('Scanning for sessions...');
  spinner.start();

  // Find all session files
  const sessionFiles = findAllSessionFiles(CLAUDE_DIR);
  const totalFiles = sessionFiles.length;

  if (totalFiles === 0) {
    spinner.succeed('No Claude Code sessions found yet');
    console.log(chalk.dim('  Start using Claude Code, then run cmem to see your sessions\n'));
    return;
  }

  // Check how many are already indexed
  const statsBefore = getStats();
  const alreadyIndexed = statsBefore.sessionCount;

  if (alreadyIndexed >= totalFiles) {
    spinner.succeed(`Found ${totalFiles} sessions (all indexed)`);
    console.log('');
    return;
  }

  spinner.update(`Found ${totalFiles} sessions, indexing...`);

  // Check if embeddings are ready
  const embeddingsReady = isReady();

  let processed = 0;
  let newlyIndexed = 0;

  for (const filePath of sessionFiles) {
    processed++;
    const wasNew = await indexSessionFile(filePath, embeddingsReady);
    if (wasNew) newlyIndexed++;

    // Update progress
    const percent = Math.round((processed / totalFiles) * 100);
    spinner.update(`Indexing sessions... ${percent}% (${processed}/${totalFiles})`);
  }

  spinner.succeed(`Indexed ${totalFiles} sessions (${newlyIndexed} new)`);

  // Show stats
  const statsAfter = getStats();
  console.log(chalk.dim(`  ${statsAfter.sessionCount} sessions, ${statsAfter.embeddingCount} with embeddings\n`));
}
