import chalk from 'chalk';
import { getSession, deleteSession, listSessions } from '../db/sessions.js';
import { shortId } from '../utils/format.js';

export async function deleteCommand(id: string): Promise<void> {
  // Support partial ID matching
  let session = getSession(id);

  if (!session) {
    // Try partial match
    const sessions = listSessions();
    const match = sessions.find(s => s.id.startsWith(id));
    if (match) {
      session = match;
    }
  }

  if (!session) {
    console.log(chalk.red(`Session not found: ${id}`));
    console.log(chalk.dim('Run: cmem list to see available sessions'));
    return;
  }

  const deleted = deleteSession(session.id);

  if (deleted) {
    console.log(chalk.green(`Deleted session: ${shortId(session.id)} - ${session.title}`));
  } else {
    console.log(chalk.red('Failed to delete session.'));
  }
}
