import React from 'react';
import { Box, Text } from 'ink';
import type { SessionWithFavorite } from '../hooks/useSessions.js';
import { truncate } from '../../utils/format.js';

interface PreviewProps {
  session: SessionWithFavorite | null;
}

export const Preview: React.FC<PreviewProps> = ({ session }) => {
  if (!session) {
    return null;
  }

  const summary = session.summary
    ? truncate(session.summary, 200)
    : 'No summary available';

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor="gray"
      paddingX={1}
      paddingY={0}
      marginTop={1}
    >
      <Box>
        <Text bold>Preview</Text>
        {session.isFavorite && <Text color="yellow"> ⭐</Text>}
        {session.projectPath && (
          <Text bold color="blue">  📁 {session.projectPath}</Text>
        )}
      </Box>
      <Text wrap="wrap">{summary}</Text>
      <Text dimColor>Messages: {session.messageCount}</Text>
    </Box>
  );
};
