import React from 'react';
import { Box, Text } from 'ink';
import type { Project } from '../hooks/useSessions.js';
import { formatTimeAgo, truncate } from '../../utils/format.js';

interface ProjectListProps {
  projects: Project[];
  selectedIndex: number;
  onSelect: (index: number) => void;
}

export const ProjectList: React.FC<ProjectListProps> = ({
  projects,
  selectedIndex,
}) => {
  if (projects.length === 0) {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor="gray"
        paddingX={1}
        paddingY={0}
      >
        <Text bold>Projects</Text>
        <Text dimColor>No projects found</Text>
        <Text dimColor>Start using Claude Code in a project directory</Text>
      </Box>
    );
  }

  // Show max 8 projects, centered around selected
  const visibleCount = 8;
  let startIndex = Math.max(0, selectedIndex - Math.floor(visibleCount / 2));
  const endIndex = Math.min(projects.length, startIndex + visibleCount);
  if (endIndex - startIndex < visibleCount) {
    startIndex = Math.max(0, endIndex - visibleCount);
  }

  const visibleProjects = projects.slice(startIndex, endIndex);

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor="gray"
      paddingX={1}
      paddingY={0}
    >
      <Text bold>Projects ({projects.length})</Text>
      {visibleProjects.map((project, i) => {
        const actualIndex = startIndex + i;
        const isSelected = actualIndex === selectedIndex;

        return (
          <ProjectItem
            key={project.path}
            project={project}
            isSelected={isSelected}
          />
        );
      })}
      {projects.length > visibleCount && (
        <Text dimColor>
          {startIndex > 0 ? '↑ more above' : ''}
          {startIndex > 0 && endIndex < projects.length ? ' | ' : ''}
          {endIndex < projects.length ? '↓ more below' : ''}
        </Text>
      )}
    </Box>
  );
};

interface ProjectItemProps {
  project: Project;
  isSelected: boolean;
}

const ProjectItem: React.FC<ProjectItemProps> = ({ project, isSelected }) => {
  const displayName = truncate(project.name, 40);
  const sessions = `${project.sessionCount} session${project.sessionCount !== 1 ? 's' : ''}`;
  const messages = `${project.totalMessages} msgs`;
  const updated = formatTimeAgo(project.lastUpdated);
  // Show position number if manually sorted
  const orderBadge = project.sortOrder !== null ? `${project.sortOrder + 1}.` : '  ';

  return (
    <Box>
      <Text color={isSelected ? 'cyan' : undefined}>
        {isSelected ? '▸ ' : '  '}
      </Text>
      <Text dimColor>{orderBadge.padStart(3)} </Text>
      <Text color="blue">📁 </Text>
      <Text bold={isSelected} color={isSelected ? 'cyan' : undefined} wrap="truncate">
        {displayName.padEnd(35)}
      </Text>
      <Text dimColor> {sessions.padEnd(12)}</Text>
      <Text dimColor> {messages.padEnd(10)}</Text>
      <Text dimColor>{updated.padStart(10)}</Text>
    </Box>
  );
};
