import chalk from 'chalk';
import { startMcpServer } from '../mcp/server.js';

export async function mcpCommand(): Promise<void> {
  // When running as MCP server, we don't want to log to stdout
  // as it's used for JSON-RPC communication
  // Instead, log to stderr for debugging
  console.error(chalk.cyan('Starting cmem MCP server...'));

  try {
    await startMcpServer();
  } catch (err) {
    console.error(chalk.red('MCP server error:'), err);
    process.exit(1);
  }
}
