/**
 * GUI Command
 *
 * Launches the web-based lesson management interface.
 */

import chalk from 'chalk';
import { startServer } from '../api/server.js';

interface GuiOptions {
  port?: string;
  open?: boolean;
}

export async function guiCommand(options: GuiOptions): Promise<void> {
  const port = options.port ? parseInt(options.port, 10) : 3848;

  console.log(chalk.cyan('Starting CMEM GUI...'));
  console.log('');

  await startServer({
    port,
    open: options.open !== false, // Default to opening browser
  });
}
