import chalk from 'chalk';
import { listHumanSessions, listSessions } from '../db/sessions.js';
import { formatTimeAgo, shortId, truncate } from '../utils/format.js';

interface ListOptions {
  all?: boolean;
}

export async function listCommand(options: ListOptions = {}): Promise<void> {
  // Use listHumanSessions by default, listSessions with --all flag
  const sessions = options.all ? listSessions() : listHumanSessions();

  if (sessions.length === 0) {
    console.log(chalk.yellow('No saved sessions.'));
    console.log(chalk.dim('Run: cmem save --latest'));
    return;
  }

  console.log(chalk.cyan(`Saved Sessions (${sessions.length})\n`));

  // Table header
  console.log(
    chalk.dim(
      'ID'.padEnd(10) +
      'Title'.padEnd(40) +
      'Msgs'.padEnd(6) +
      'Updated'.padEnd(10) +
      'Project'
    )
  );
  console.log(chalk.dim('─'.repeat(90)));

  for (const session of sessions) {
    const id = shortId(session.id);
    const title = truncate(session.title, 38);
    const msgs = String(session.messageCount).padStart(4);
    const updated = formatTimeAgo(session.updatedAt);
    const project = session.projectPath ? truncate(session.projectPath, 25) : chalk.dim('—');

    console.log(
      chalk.white(id.padEnd(10)) +
      title.padEnd(40) +
      chalk.dim(msgs.padEnd(6)) +
      chalk.dim(updated.padEnd(10)) +
      chalk.dim(project)
    );
  }

  console.log(chalk.dim('\n─'.repeat(90)));
  console.log(chalk.dim('Use: cmem restore <id> to restore a session'));
}
