import { spawn } from 'child_process';
import { execSync } from 'child_process';

export interface ClaudeResponse {
  success: boolean;
  content: string;
  error?: string;
  inputTokens?: number;
  outputTokens?: number;
  costUsd?: number;
  durationMs?: number;
}

/**
 * Get the path to the Claude CLI
 */
function getClaudePath(): string | null {
  try {
    const result = execSync('which claude', { encoding: 'utf-8' }).trim();
    return result || null;
  } catch {
    return null;
  }
}

/**
 * Parse a single line of NDJSON from Claude's stream-json output
 */
interface ParsedChunk {
  type: 'text' | 'done' | 'error' | 'skip';
  content?: string;
  inputTokens?: number;
  outputTokens?: number;
  costUsd?: number;
  durationMs?: number;
}

function parseStreamJsonLine(line: string): ParsedChunk | null {
  if (!line.trim()) return null;

  try {
    const data = JSON.parse(line);

    if (data.type === 'assistant') {
      // Assistant message with content blocks
      if (data.message?.content && Array.isArray(data.message.content)) {
        const textBlocks: string[] = [];

        for (const block of data.message.content) {
          if (block.type === 'text' && block.text) {
            textBlocks.push(block.text);
          }
        }

        if (textBlocks.length > 0) {
          return { type: 'text', content: textBlocks.join('\n') };
        }
      }
    } else if (data.type === 'content_block_delta') {
      // Streaming text delta
      if (data.delta?.type === 'text_delta' && data.delta.text) {
        return { type: 'text', content: data.delta.text };
      }
    } else if (data.type === 'result') {
      // Final result
      if (data.is_error) {
        return { type: 'error', content: data.result || 'Unknown error' };
      }
      const usage = data.usage || {};
      const inputTokens = (usage.input_tokens || 0) + (usage.cache_read_input_tokens || 0);
      const outputTokens = usage.output_tokens || 0;
      return {
        type: 'done',
        inputTokens,
        outputTokens,
        costUsd: data.total_cost_usd,
        durationMs: data.duration_ms,
      };
    } else if (data.type === 'error') {
      return {
        type: 'error',
        content: data.error?.message || JSON.stringify(data.error) || 'Unknown error',
      };
    }

    // Skip other message types (system, message_start, etc.)
    return { type: 'skip' };
  } catch {
    return null;
  }
}

/**
 * Run a prompt through Claude CLI and return the response
 * Uses print mode (-p) with stream-json output for structured responses
 */
export async function runClaudePrompt(
  prompt: string,
  options: {
    model?: 'opus' | 'sonnet' | 'haiku';
    maxTokens?: number;
  } = {}
): Promise<ClaudeResponse> {
  const claudePath = getClaudePath();
  if (!claudePath) {
    return {
      success: false,
      content: '',
      error: 'Claude CLI not found. Please install Claude Code CLI.',
    };
  }

  const { model = 'haiku' } = options;

  const args = [
    '-p', prompt,
    '--output-format', 'stream-json',
    '--verbose', // Required when using stream-json with -p
    '--model', model,
    '--permission-mode', 'plan', // Read-only, no tools needed for summarization
  ];

  return new Promise((resolve) => {
    const childProcess = spawn(claudePath, args, {
      env: {
        ...process.env,
        CI: 'true', // Prevent interactive prompts
      },
      stdio: ['pipe', 'pipe', 'pipe'],
    });

    // Close stdin since we're using -p flag
    childProcess.stdin?.end();

    let buffer = '';
    const textChunks: string[] = [];
    let finalResult: ParsedChunk | null = null;
    let errorContent = '';

    childProcess.stdout?.on('data', (data: Buffer) => {
      buffer += data.toString();

      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (!line.trim()) continue;

        const chunk = parseStreamJsonLine(line);
        if (chunk) {
          if (chunk.type === 'text' && chunk.content) {
            textChunks.push(chunk.content);
          } else if (chunk.type === 'done') {
            finalResult = chunk;
          } else if (chunk.type === 'error' && chunk.content) {
            errorContent = chunk.content;
          }
        }
      }
    });

    childProcess.stderr?.on('data', (data: Buffer) => {
      const text = data.toString().toLowerCase();
      if (text.includes('error') || text.includes('failed')) {
        errorContent = data.toString().trim();
      }
    });

    childProcess.on('close', (code) => {
      // Process remaining buffer
      if (buffer.trim()) {
        const chunk = parseStreamJsonLine(buffer);
        if (chunk) {
          if (chunk.type === 'text' && chunk.content) {
            textChunks.push(chunk.content);
          } else if (chunk.type === 'done') {
            finalResult = chunk;
          } else if (chunk.type === 'error' && chunk.content) {
            errorContent = chunk.content;
          }
        }
      }

      const content = textChunks.join('');

      if (errorContent && !content) {
        resolve({
          success: false,
          content: '',
          error: errorContent,
        });
      } else {
        resolve({
          success: code === 0 && content.length > 0,
          content,
          error: errorContent || undefined,
          inputTokens: finalResult?.inputTokens,
          outputTokens: finalResult?.outputTokens,
          costUsd: finalResult?.costUsd,
          durationMs: finalResult?.durationMs,
        });
      }
    });

    childProcess.on('error', (err) => {
      resolve({
        success: false,
        content: '',
        error: err.message,
      });
    });

    // Timeout after 60 seconds
    setTimeout(() => {
      childProcess.kill('SIGTERM');
      resolve({
        success: false,
        content: textChunks.join(''),
        error: 'Request timed out after 60 seconds',
      });
    }, 60000);
  });
}

/**
 * Check if Claude CLI is available
 */
export function isClaudeCliAvailable(): boolean {
  return getClaudePath() !== null;
}
