import chalk from 'chalk';
import { searchSessions } from '../db/vectors.js';
import { getEmbedding, initializeEmbeddings, isReady } from '../embeddings/index.js';
import { formatTimeAgo, shortId, truncate } from '../utils/format.js';

export async function searchCommand(query: string): Promise<void> {
  console.log(chalk.cyan(`Searching for: "${query}"...\n`));

  // Initialize embeddings (downloads model if needed)
  if (!isReady()) {
    console.log(chalk.dim('Initializing embedding model...'));
    try {
      await initializeEmbeddings((progress) => {
        if (progress.status === 'downloading' && progress.progress !== undefined) {
          process.stdout.write(`\r${chalk.dim(`Downloading model... ${Math.round(progress.progress)}%`)}`);
        }
      });
      console.log(chalk.green('\r✓ Model ready                    \n'));
    } catch (err) {
      console.log(chalk.red('Failed to initialize embedding model.'));
      console.log(chalk.dim(String(err)));
      return;
    }
  }

  try {
    // Generate query embedding
    const queryEmbedding = await getEmbedding(query);

    // Search for similar sessions
    const results = searchSessions(queryEmbedding, 10);

    if (results.length === 0) {
      console.log(chalk.yellow('No matching sessions found.'));
      console.log(chalk.dim('Try a different search query or save more sessions.'));
      return;
    }

    console.log(chalk.green(`Found ${results.length} matching session(s)\n`));

    // Table header
    console.log(
      chalk.dim(
        'ID'.padEnd(10) +
        'Title'.padEnd(40) +
        'Msgs'.padEnd(6) +
        'Updated'
      )
    );
    console.log(chalk.dim('─'.repeat(70)));

    for (const session of results) {
      const id = shortId(session.id);
      const title = truncate(session.title, 38);
      const msgs = String(session.messageCount).padStart(4);
      const updated = formatTimeAgo(session.updatedAt);

      console.log(
        chalk.white(id.padEnd(10)) +
        title.padEnd(40) +
        chalk.dim(msgs.padEnd(6)) +
        chalk.dim(updated)
      );

      // Show summary snippet
      if (session.summary) {
        console.log(chalk.dim('  ' + truncate(session.summary, 65)));
      }
    }

    console.log(chalk.dim('\n─'.repeat(70)));
    console.log(chalk.dim('Use: cmem restore <id> to restore a session'));
  } catch (err) {
    console.log(chalk.red('Search failed.'));
    console.log(chalk.dim(String(err)));
  }
}
