import { program } from 'commander';
import { render } from 'ink';
import React from 'react';
import { existsSync, readFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { spawn } from 'child_process';
import { App } from './ui/App.js';
import { saveCommand } from './commands/save.js';
import { listCommand } from './commands/list.js';
import { searchCommand } from './commands/search.js';
import { restoreCommand } from './commands/restore.js';
import { deleteCommand } from './commands/delete.js';
import { statsCommand } from './commands/stats.js';
import { watchCommand } from './commands/watch.js';
import { mcpCommand } from './commands/mcp.js';
import { setupCommand, shouldRunSetup } from './commands/setup.js';
import { purgeCommand } from './commands/purge.js';
import { synthesizeCommand } from './commands/synthesize.js';
import { guiCommand } from './commands/gui.js';

// Store session to resume after TUI exits
let sessionToResume: { sessionId: string; projectPath: string | null } | null = null;

// Get version from package.json
function getVersion(): string {
  try {
    const __filename = fileURLToPath(import.meta.url);
    const __dirname = dirname(__filename);
    const packagePath = join(__dirname, '..', 'package.json');
    if (existsSync(packagePath)) {
      const pkg = JSON.parse(readFileSync(packagePath, 'utf-8'));
      return pkg.version || '0.1.0';
    }
  } catch {
    // Ignore
  }
  return '0.1.0';
}

program
  .name('cmem')
  .description('Persistent session storage for Claude Code CLI')
  .version(getVersion())
  .option('-l, --local', 'Filter to sessions from current directory')
  .action(async (options) => {
    // Check if we should run setup (first run via npx)
    if (shouldRunSetup()) {
      await setupCommand();
      return;
    }

    // Handle resume callback from TUI
    const handleResume = (sessionId: string, projectPath: string | null) => {
      sessionToResume = { sessionId, projectPath };
    };

    // Determine project filter
    const projectFilter = options.local ? process.cwd() : null;

    // Default action: launch TUI
    const { waitUntilExit } = render(React.createElement(App, { onResume: handleResume, projectFilter }));
    await waitUntilExit();

    // If user selected a session to resume, spawn Claude
    if (sessionToResume) {
      const args = ['--resume', sessionToResume.sessionId];

      // Use project path if available, otherwise current directory
      const cwd = sessionToResume.projectPath || process.cwd();

      console.log(`\nResuming session in: ${cwd}\n`);

      // Spawn Claude with inherited stdio so it takes over the terminal
      const child = spawn('claude', args, {
        cwd,
        stdio: 'inherit',
        shell: true,
      });

      child.on('error', (err) => {
        console.error('Failed to start Claude:', err.message);
        process.exit(1);
      });

      child.on('exit', (code) => {
        process.exit(code || 0);
      });
    }
  });

program
  .command('setup')
  .description('Run interactive setup wizard')
  .action(async () => {
    await setupCommand();
  });

program
  .command('save')
  .description('Save a Claude Code session')
  .option('-t, --title <title>', 'Custom title')
  .option('--latest', 'Auto-save most recent session')
  .action(async (options) => {
    await saveCommand(options);
  });

program
  .command('list')
  .description('List saved sessions (human sessions only by default)')
  .option('-a, --all', 'Show all sessions including automated ones')
  .action(async (options) => {
    await listCommand(options);
  });

program
  .command('search <query>')
  .description('Semantic search across sessions')
  .action(async (query) => {
    await searchCommand(query);
  });

program
  .command('restore <id>')
  .description('Restore a session')
  .option('--copy', 'Copy to clipboard')
  .option('--format <format>', 'Output format: context|json|markdown', 'context')
  .action(async (id, options) => {
    await restoreCommand(id, options);
  });

program
  .command('delete <id>')
  .description('Delete a session')
  .action(async (id) => {
    await deleteCommand(id);
  });

program
  .command('purge')
  .description('Delete old sessions to free up space')
  .option('-d, --days <n>', 'Delete sessions older than N days (default: 30)')
  .option('--dry-run', 'Preview what would be deleted without making changes')
  .option('-f, --force', 'Skip confirmation prompt')
  .action(async (options) => {
    await purgeCommand(options);
  });

program
  .command('stats')
  .description('Show storage statistics')
  .action(async () => {
    await statsCommand();
  });

program
  .command('watch')
  .description('Watch for Claude Code session changes and auto-sync')
  .option('-v, --verbose', 'Show detailed output')
  .option('--embed-threshold <chars>', 'Re-embed after this many new chars', '500')
  .action(async (options) => {
    await watchCommand({
      verbose: options.verbose,
      embedThreshold: parseInt(options.embedThreshold, 10),
    });
  });

program
  .command('mcp')
  .description('Start MCP server for Claude Code integration')
  .action(async () => {
    await mcpCommand();
  });

program
  .command('synthesize')
  .description('Extract lessons from sessions in the synthesis queue')
  .option('-n, --limit <n>', 'Maximum number of sessions to process', '5')
  .option('-s, --status', 'Show queue status only')
  .action(async (options) => {
    await synthesizeCommand(options);
  });

program
  .command('gui')
  .description('Launch the web-based lesson management interface')
  .option('-p, --port <port>', 'Port to run server on', '3848')
  .option('--no-open', 'Do not open browser automatically')
  .action(async (options) => {
    await guiCommand(options);
  });

program.parse();
