import { statSync, existsSync, unlinkSync, readdirSync, rmdirSync } from 'fs';
import { join, dirname } from 'path';
import { DB_PATH, BACKUPS_DIR, getBackupPath } from '../utils/config.js';
import { getDatabase } from './index.js';

/**
 * Get database file size in bytes
 */
export function getDatabaseSize(): number {
  try {
    const stats = statSync(DB_PATH);
    return stats.size;
  } catch {
    return 0;
  }
}

/**
 * Get total size of the backups directory in bytes
 */
export function getBackupsDirSize(): number {
  try {
    if (!existsSync(BACKUPS_DIR)) return 0;
    return getDirSize(BACKUPS_DIR);
  } catch {
    return 0;
  }
}

/**
 * Recursively get directory size
 */
function getDirSize(dirPath: string): number {
  let size = 0;
  try {
    const entries = readdirSync(dirPath, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = join(dirPath, entry.name);
      if (entry.isDirectory()) {
        size += getDirSize(fullPath);
      } else {
        try {
          size += statSync(fullPath).size;
        } catch {
          // Skip files we can't stat
        }
      }
    }
  } catch {
    // Skip directories we can't read
  }
  return size;
}

/**
 * Get total storage size (database + backups)
 */
export function getTotalStorageSize(): number {
  return getDatabaseSize() + getBackupsDirSize();
}

/**
 * Preview what purging would delete
 */
export interface PurgePreview {
  sessionsToDelete: number;
  messagesInvolved: number;
  oldestSessionDate: string;
  newestSessionDate: string;
  backupFilesToDelete: number;
  backupBytesToFree: number;
}

/**
 * Get a preview of what would be purged
 * Excludes starred (favorited) sessions
 */
export function getPurgePreview(days: number): PurgePreview {
  const db = getDatabase();

  // Find sessions that would be deleted (older than N days, not favorited)
  const result = db.prepare(`
    SELECT
      COUNT(*) as sessionCount,
      COALESCE(MIN(s.updated_at), '') as oldestDate,
      COALESCE(MAX(s.updated_at), '') as newestDate
    FROM sessions s
    LEFT JOIN favorites f ON f.type = 'session' AND f.value = s.id
    WHERE s.updated_at < datetime('now', '-' || ? || ' days')
      AND f.id IS NULL
  `).get(days) as { sessionCount: number; oldestDate: string; newestDate: string };

  // Count messages in those sessions
  const messageResult = db.prepare(`
    SELECT COALESCE(SUM(s.message_count), 0) as messageCount
    FROM sessions s
    LEFT JOIN favorites f ON f.type = 'session' AND f.value = s.id
    WHERE s.updated_at < datetime('now', '-' || ? || ' days')
      AND f.id IS NULL
  `).get(days) as { messageCount: number };

  // Get source files to calculate backup sizes
  const sessionsWithSourceFiles = db.prepare(`
    SELECT s.source_file as sourceFile
    FROM sessions s
    LEFT JOIN favorites f ON f.type = 'session' AND f.value = s.id
    WHERE s.updated_at < datetime('now', '-' || ? || ' days')
      AND f.id IS NULL
      AND s.source_file IS NOT NULL
  `).all(days) as { sourceFile: string }[];

  // Calculate backup files info
  let backupFilesToDelete = 0;
  let backupBytesToFree = 0;

  for (const session of sessionsWithSourceFiles) {
    const backupPath = getBackupPath(session.sourceFile);
    if (existsSync(backupPath)) {
      backupFilesToDelete++;
      try {
        backupBytesToFree += statSync(backupPath).size;
      } catch {
        // Ignore stat errors
      }
    }
  }

  return {
    sessionsToDelete: result.sessionCount,
    messagesInvolved: messageResult.messageCount,
    oldestSessionDate: result.oldestDate ? formatDate(result.oldestDate) : '',
    newestSessionDate: result.newestDate ? formatDate(result.newestDate) : '',
    backupFilesToDelete,
    backupBytesToFree,
  };
}

/**
 * Delete sessions older than N days, excluding starred sessions
 * Also deletes associated backup files
 * Returns the count of sessions deleted
 */
export function purgeOldSessions(days: number): { sessionsDeleted: number; backupsDeleted: number } {
  const db = getDatabase();

  // Get the IDs and source files of sessions to delete
  const sessionsToDelete = db.prepare(`
    SELECT s.id, s.source_file as sourceFile FROM sessions s
    LEFT JOIN favorites f ON f.type = 'session' AND f.value = s.id
    WHERE s.updated_at < datetime('now', '-' || ? || ' days')
      AND f.id IS NULL
  `).all(days) as { id: string; sourceFile: string | null }[];

  if (sessionsToDelete.length === 0) {
    return { sessionsDeleted: 0, backupsDeleted: 0 };
  }

  // Delete backup files first (outside transaction since it's filesystem)
  let backupsDeleted = 0;
  for (const session of sessionsToDelete) {
    if (session.sourceFile) {
      const backupPath = getBackupPath(session.sourceFile);
      if (existsSync(backupPath)) {
        try {
          unlinkSync(backupPath);
          backupsDeleted++;

          // Try to remove empty parent directory
          const parentDir = dirname(backupPath);
          try {
            const remaining = readdirSync(parentDir);
            if (remaining.length === 0) {
              rmdirSync(parentDir);
            }
          } catch {
            // Ignore directory cleanup errors
          }
        } catch {
          // Ignore file deletion errors
        }
      }
    }
  }

  // Delete from database
  const transaction = db.transaction(() => {
    for (const session of sessionsToDelete) {
      // Delete from vector table
      db.prepare('DELETE FROM session_embeddings WHERE session_id = ?').run(session.id);
      // Delete embedding state
      db.prepare('DELETE FROM embedding_state WHERE session_id = ?').run(session.id);
      // Delete messages
      db.prepare('DELETE FROM messages WHERE session_id = ?').run(session.id);
      // Delete session
      db.prepare('DELETE FROM sessions WHERE id = ?').run(session.id);
    }
  });

  transaction();

  return { sessionsDeleted: sessionsToDelete.length, backupsDeleted };
}

/**
 * Format an ISO date string to a more readable format
 */
function formatDate(isoDate: string): string {
  try {
    const date = new Date(isoDate);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return isoDate;
  }
}

/**
 * Format bytes to human readable string
 */
export function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 B';

  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));

  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`;
}
