import { existsSync } from 'fs';
import { join } from 'path';
import {
  EMBEDDING_MODEL,
  MODELS_DIR,
  MAX_EMBEDDING_CHARS,
  MAX_MESSAGE_PREVIEW_CHARS,
  ensureModelsDir,
} from '../utils/config.js';

// Lazy load transformers.js
let transformersModule: typeof import('@xenova/transformers') | null = null;
let pipeline: any = null;
let initialized = false;

async function getTransformers() {
  if (!transformersModule) {
    transformersModule = await import('@xenova/transformers');
  }
  return transformersModule;
}

export interface InitProgress {
  status: 'checking' | 'downloading' | 'loading' | 'ready';
  file?: string;
  progress?: number;
}

/**
 * Check if the model is already cached locally
 */
export function isModelCached(): boolean {
  // Transformers.js stores models at models/org/model-name/
  const modelCachePath = join(MODELS_DIR, EMBEDDING_MODEL);
  return existsSync(modelCachePath);
}

/**
 * Initialize the embedding pipeline
 * Downloads the model on first use with progress callback
 */
export async function initializeEmbeddings(
  onProgress?: (progress: InitProgress) => void
): Promise<void> {
  if (initialized && pipeline) {
    return;
  }

  ensureModelsDir();

  const { pipeline: createPipeline, env } = await getTransformers();

  // Configure cache directory
  env.cacheDir = MODELS_DIR;

  // Check if model is cached
  const cached = isModelCached();
  if (cached) {
    env.allowRemoteModels = false; // Use local cache only
    onProgress?.({ status: 'loading' });
  } else {
    onProgress?.({ status: 'downloading' });
  }

  // Create the pipeline with progress callback
  pipeline = await createPipeline('feature-extraction', EMBEDDING_MODEL, {
    progress_callback: onProgress
      ? (progress: { status: string; file?: string; progress?: number }) => {
          if (progress.status === 'progress' && progress.file && progress.progress !== undefined) {
            onProgress({
              status: 'downloading',
              file: progress.file,
              progress: progress.progress,
            });
          }
        }
      : undefined,
  });

  initialized = true;
  onProgress?.({ status: 'ready' });
}

/**
 * Check if embeddings are ready to use
 */
export function isReady(): boolean {
  return initialized && pipeline !== null;
}

/**
 * Generate an embedding vector for text
 */
export async function getEmbedding(text: string): Promise<number[]> {
  // Initialize if needed (will use cached model if available)
  if (!initialized) {
    await initializeEmbeddings();
  }

  // Truncate to max chars
  const truncated = text.slice(0, MAX_EMBEDDING_CHARS);

  // Generate embedding
  const output = await pipeline(truncated, {
    pooling: 'mean',
    normalize: true,
  });

  // Convert to regular array
  return Array.from(output.data);
}

/**
 * Create embedding text from session data
 * Combines title, summary, and key messages for semantic search
 */
export function createEmbeddingText(
  title: string,
  summary: string | undefined,
  messages: Array<{ role: string; content: string }>
): string {
  const parts: string[] = [];

  // Add title
  parts.push(`Title: ${title}`);

  // Add summary if available
  if (summary) {
    parts.push(`Summary: ${summary}`);
  }

  // Add first 5 user messages (truncated)
  const userMessages = messages
    .filter((m) => m.role === 'user')
    .slice(0, 5)
    .map((m) => m.content.slice(0, MAX_MESSAGE_PREVIEW_CHARS));

  if (userMessages.length > 0) {
    parts.push('User messages:');
    parts.push(...userMessages);
  }

  // Add first 3 assistant responses (truncated) for context
  const assistantMessages = messages
    .filter((m) => m.role === 'assistant')
    .slice(0, 3)
    .map((m) => m.content.slice(0, MAX_MESSAGE_PREVIEW_CHARS));

  if (assistantMessages.length > 0) {
    parts.push('Assistant responses:');
    parts.push(...assistantMessages);
  }

  return parts.join('\n\n');
}
