/**
 * Express API Routes for GUI
 *
 * Provides REST endpoints for lesson management.
 */

import { Router, type Request, type Response } from 'express';
import {
  createLesson,
  updateLesson,
  deleteLesson,
  archiveLesson,
  getLesson,
  getLessonsByProject,
  getAllLessons,
  recordLessonValidation,
  recordLessonRejection,
  getLessonStats,
  getQueueStatus,
  getDistinctProjects,
} from '../db/lessons.js';
import type { LessonCategory, CreateLessonInput, UpdateLessonInput } from '../learning/types.js';

export const apiRouter = Router();

// GET /api/lessons - List lessons with optional filters
apiRouter.get('/lessons', (req: Request, res: Response) => {
  try {
    const {
      projectPath,
      category,
      archived,
      minConfidence,
      limit,
    } = req.query;

    let lessons;

    if (projectPath) {
      lessons = getLessonsByProject(projectPath as string, {
        category: category as LessonCategory | undefined,
        archived: archived === 'true',
        minConfidence: minConfidence ? parseFloat(minConfidence as string) : undefined,
        limit: limit ? parseInt(limit as string, 10) : undefined,
      });
    } else {
      lessons = getAllLessons({
        category: category as LessonCategory | undefined,
        archived: archived === 'true',
        minConfidence: minConfidence ? parseFloat(minConfidence as string) : undefined,
        limit: limit ? parseInt(limit as string, 10) : undefined,
      });
    }

    res.json(lessons);
  } catch (error) {
    console.error('Error fetching lessons:', error);
    res.status(500).json({ message: 'Failed to fetch lessons' });
  }
});

// GET /api/lessons/:id - Get single lesson
apiRouter.get('/lessons/:id', (req: Request, res: Response) => {
  try {
    const lesson = getLesson(req.params.id);
    if (!lesson) {
      res.status(404).json({ message: 'Lesson not found' });
      return;
    }
    res.json(lesson);
  } catch (error) {
    console.error('Error fetching lesson:', error);
    res.status(500).json({ message: 'Failed to fetch lesson' });
  }
});

// POST /api/lessons - Create lesson
apiRouter.post('/lessons', (req: Request, res: Response) => {
  try {
    const input: CreateLessonInput = req.body;

    if (!input.projectPath || !input.category || !input.title || !input.triggerContext || !input.insight) {
      res.status(400).json({ message: 'Missing required fields' });
      return;
    }

    const lesson = createLesson(input);
    res.status(201).json(lesson);
  } catch (error) {
    console.error('Error creating lesson:', error);
    res.status(500).json({ message: 'Failed to create lesson' });
  }
});

// PUT /api/lessons/:id - Update lesson
apiRouter.put('/lessons/:id', (req: Request, res: Response) => {
  try {
    const existing = getLesson(req.params.id);
    if (!existing) {
      res.status(404).json({ message: 'Lesson not found' });
      return;
    }

    const updates: UpdateLessonInput = req.body;
    const lesson = updateLesson(req.params.id, updates);
    res.json(lesson);
  } catch (error) {
    console.error('Error updating lesson:', error);
    res.status(500).json({ message: 'Failed to update lesson' });
  }
});

// DELETE /api/lessons/:id - Delete lesson
apiRouter.delete('/lessons/:id', (req: Request, res: Response) => {
  try {
    const existing = getLesson(req.params.id);
    if (!existing) {
      res.status(404).json({ message: 'Lesson not found' });
      return;
    }

    deleteLesson(req.params.id);
    res.status(204).send();
  } catch (error) {
    console.error('Error deleting lesson:', error);
    res.status(500).json({ message: 'Failed to delete lesson' });
  }
});

// POST /api/lessons/:id/validate - Validate lesson (boost confidence)
apiRouter.post('/lessons/:id/validate', (req: Request, res: Response) => {
  try {
    const existing = getLesson(req.params.id);
    if (!existing) {
      res.status(404).json({ message: 'Lesson not found' });
      return;
    }

    const { comment } = req.body;
    recordLessonValidation(req.params.id, comment);

    // Boost confidence
    const newConfidence = Math.min(1.0, existing.confidence + 0.1);
    const lesson = updateLesson(req.params.id, { confidence: newConfidence });
    res.json(lesson);
  } catch (error) {
    console.error('Error validating lesson:', error);
    res.status(500).json({ message: 'Failed to validate lesson' });
  }
});

// POST /api/lessons/:id/reject - Reject lesson (reduce confidence)
apiRouter.post('/lessons/:id/reject', (req: Request, res: Response) => {
  try {
    const existing = getLesson(req.params.id);
    if (!existing) {
      res.status(404).json({ message: 'Lesson not found' });
      return;
    }

    const { comment } = req.body;
    recordLessonRejection(req.params.id, comment);

    // Reduce confidence
    const newConfidence = Math.max(0.0, existing.confidence - 0.2);

    // Auto-archive if very low confidence
    if (newConfidence < 0.1) {
      archiveLesson(req.params.id);
    }

    const lesson = updateLesson(req.params.id, { confidence: newConfidence });
    res.json(lesson);
  } catch (error) {
    console.error('Error rejecting lesson:', error);
    res.status(500).json({ message: 'Failed to reject lesson' });
  }
});

// POST /api/lessons/:id/archive - Archive lesson
apiRouter.post('/lessons/:id/archive', (req: Request, res: Response) => {
  try {
    const existing = getLesson(req.params.id);
    if (!existing) {
      res.status(404).json({ message: 'Lesson not found' });
      return;
    }

    archiveLesson(req.params.id);
    const lesson = getLesson(req.params.id);
    res.json(lesson);
  } catch (error) {
    console.error('Error archiving lesson:', error);
    res.status(500).json({ message: 'Failed to archive lesson' });
  }
});

// GET /api/stats - Get statistics
apiRouter.get('/stats', (_req: Request, res: Response) => {
  try {
    const lessonStats = getLessonStats();
    const queueStatus = getQueueStatus();

    res.json({
      ...lessonStats,
      synthesisQueue: queueStatus,
    });
  } catch (error) {
    console.error('Error fetching stats:', error);
    res.status(500).json({ message: 'Failed to fetch stats' });
  }
});

// GET /api/projects - Get distinct projects
apiRouter.get('/projects', (_req: Request, res: Response) => {
  try {
    const projects = getDistinctProjects();
    res.json(projects);
  } catch (error) {
    console.error('Error fetching projects:', error);
    res.status(500).json({ message: 'Failed to fetch projects' });
  }
});
