import React, { useState, useEffect, useCallback } from 'react';
import { Box, Text, useInput, useApp } from 'ink';
import TextInput from 'ink-text-input';
import Spinner from 'ink-spinner';
import { basename, dirname } from 'path';
import { existsSync } from 'fs';
import { hasBackup, restoreFromBackup, DB_SIZE_ALERT_THRESHOLD, DEFAULT_PURGE_DAYS } from '../utils/config.js';
import { getTotalStorageSize, getDatabaseSize, getBackupsDirSize, getPurgePreview, purgeOldSessions, formatBytes, type PurgePreview } from '../db/maintenance.js';
import { getStats } from '../db/sessions.js';
import { StorageScreen, type StorageStats, type PurgeOption } from './components/StorageScreen.js';
import { Header } from './components/Header.js';
import { SearchInput } from './components/SearchInput.js';
import { SessionList } from './components/SessionList.js';
import { ProjectList } from './components/ProjectList.js';
import { Preview } from './components/Preview.js';
import { useSessions } from './hooks/useSessions.js';
import { renameSession } from '../db/sessions.js';

type Mode = 'list' | 'search' | 'confirm-delete' | 'rename' | 'sort-project' | 'db-size-alert' | 'confirm-purge' | 'storage' | 'storage-confirm';
type TabType = 'global' | 'projects';
type ViewType = 'sessions' | 'projects' | 'project-sessions'; // What we're currently viewing

export interface AppProps {
  onResume?: (sessionId: string, projectPath: string | null) => void;
  projectFilter?: string | null;
}

export const App: React.FC<AppProps> = ({ onResume, projectFilter: initialProjectFilter }) => {
  const { exit } = useApp();
  const {
    sessions,
    projects,
    loading,
    embeddingsReady,
    projectFilter,
    setProjectFilter,
    search,
    clearSearch,
    deleteSession,
    refresh,
    toggleFavorite,
    moveProject,
  } = useSessions({ projectFilter: initialProjectFilter });

  const [selectedIndex, setSelectedIndex] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');
  const [mode, setMode] = useState<Mode>('list');
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState('');
  const [currentTab, setCurrentTab] = useState<TabType>('global');
  const [selectedProjectPath, setSelectedProjectPath] = useState<string | null>(null);
  const [renderKey, setRenderKey] = useState(0);
  const [dbSizeAlertShown, setDbSizeAlertShown] = useState(false);
  const [purgePreview, setPurgePreview] = useState<PurgePreview | null>(null);
  const [dbSize, setDbSize] = useState(0);
  const [storageStats, setStorageStats] = useState<StorageStats | null>(null);
  const [purgeOptions, setPurgeOptions] = useState<PurgeOption[]>([]);
  const [selectedPurgeOption, setSelectedPurgeOption] = useState<number | null>(null);

  // Determine current view based on tab and whether we've drilled into a project
  const getCurrentView = useCallback((): ViewType => {
    if (currentTab === 'projects') {
      return selectedProjectPath ? 'project-sessions' : 'projects';
    }
    return 'sessions';
  }, [currentTab, selectedProjectPath]);

  const currentView = getCurrentView();

  // Get sessions for current project (when viewing project-sessions)
  const projectSessions = selectedProjectPath
    ? sessions.filter(s => s.projectPath === selectedProjectPath)
    : [];

  // Reset selection when view changes
  useEffect(() => {
    setSelectedIndex(0);
  }, [currentTab, selectedProjectPath]);

  // Check storage size on mount and show alert if needed
  useEffect(() => {
    if (!loading && !dbSizeAlertShown) {
      const size = getTotalStorageSize();
      if (size >= DB_SIZE_ALERT_THRESHOLD) {
        const preview = getPurgePreview(DEFAULT_PURGE_DAYS);
        if (preview.sessionsToDelete > 0) {
          setDbSize(size);
          setPurgePreview(preview);
          setMode('db-size-alert');
        }
      }
      setDbSizeAlertShown(true);
    }
  }, [loading, dbSizeAlertShown]);

  // Bound check for selected index
  useEffect(() => {
    const maxIndex = currentView === 'projects'
      ? projects.length - 1
      : currentView === 'project-sessions'
        ? projectSessions.length - 1
        : sessions.length - 1;
    if (selectedIndex > maxIndex) {
      setSelectedIndex(Math.max(0, maxIndex));
    }
  }, [currentView, projects.length, projectSessions.length, sessions.length, selectedIndex]);

  // Debounced search
  useEffect(() => {
    if (mode === 'search' && searchQuery.length > 2) {
      const timer = setTimeout(() => {
        search(searchQuery);
      }, 300);
      return () => clearTimeout(timer);
    } else if (mode === 'search' && searchQuery.length === 0) {
      clearSearch();
    }
  }, [searchQuery, mode, search, clearSearch]);

  // Clear status message after 3 seconds
  useEffect(() => {
    if (statusMessage) {
      const timer = setTimeout(() => setStatusMessage(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [statusMessage]);

  const getCurrentSessions = useCallback(() => {
    if (currentView === 'project-sessions') {
      return projectSessions;
    }
    return sessions;
  }, [currentView, projectSessions, sessions]);

  const handleRestore = useCallback(() => {
    const currentSessions = getCurrentSessions();
    const session = currentSessions[selectedIndex];
    if (!session) return;

    if (session.sourceFile) {
      // Check if source file still exists, restore from backup if not
      if (!existsSync(session.sourceFile)) {
        if (hasBackup(session.sourceFile)) {
          const restored = restoreFromBackup(session.sourceFile);
          if (restored) {
            setStatusMessage('Restored session from backup');
          } else {
            setStatusMessage('Failed to restore session from backup');
            return;
          }
        } else {
          setStatusMessage('Session file deleted and no backup - cannot resume');
          return;
        }
      }

      const filename = basename(session.sourceFile);
      const claudeSessionId = filename.replace('.jsonl', '');

      // Use stored projectPath, fall back to path reconstruction if not available
      let projectPath: string | null = session.projectPath;

      // If no stored projectPath, try to reconstruct from source file path
      if (!projectPath) {
        const projectDirName = basename(dirname(session.sourceFile));
        if (projectDirName.startsWith('-')) {
          const segments = projectDirName.substring(1).split('-');
          let currentPath = '';
          let remainingSegments = [...segments];

          while (remainingSegments.length > 0) {
            let found = false;
            for (let i = remainingSegments.length; i > 0; i--) {
              const testSegment = remainingSegments.slice(0, i).join('-');
              const testPath = currentPath + '/' + testSegment;

              if (existsSync(testPath)) {
                currentPath = testPath;
                remainingSegments = remainingSegments.slice(i);
                found = true;
                break;
              }
            }

            if (!found) {
              currentPath = currentPath + '/' + remainingSegments.join('-');
              break;
            }
          }

          if (currentPath && existsSync(currentPath)) {
            projectPath = currentPath;
          }
        }
      }

      if (onResume) {
        onResume(claudeSessionId, projectPath);
        exit();
      }
    } else {
      setStatusMessage('No source file - cannot resume this session');
    }
  }, [getCurrentSessions, selectedIndex, onResume, exit]);

  const handleEnterProject = useCallback(() => {
    const project = projects[selectedIndex];
    if (project) {
      setRenderKey(k => k + 1);
      setSelectedProjectPath(project.path);
      setSelectedIndex(0);
    }
  }, [projects, selectedIndex]);

  const handleBackToProjects = useCallback(() => {
    setRenderKey(k => k + 1);
    setSelectedProjectPath(null);
    setSelectedIndex(0);
  }, []);

  const handleDelete = useCallback(() => {
    const currentSessions = getCurrentSessions();
    const session = currentSessions[selectedIndex];
    if (session) {
      deleteSession(session.id);
      setStatusMessage(`Deleted: ${session.customTitle || session.title}`);
      setMode('list');
    }
  }, [getCurrentSessions, selectedIndex, deleteSession]);

  const handleRename = useCallback(() => {
    const currentSessions = getCurrentSessions();
    const session = currentSessions[selectedIndex];
    if (session && renameValue.trim()) {
      renameSession(session.id, renameValue.trim());
      setStatusMessage(`Renamed to: ${renameValue.trim()}`);
      refresh();
    }
    setMode('list');
    setRenameValue('');
  }, [getCurrentSessions, selectedIndex, renameValue, refresh]);

  const handleClearRename = useCallback(() => {
    const currentSessions = getCurrentSessions();
    const session = currentSessions[selectedIndex];
    if (session && session.customTitle) {
      renameSession(session.id, null);
      setStatusMessage(`Cleared custom name`);
      refresh();
    }
    setMode('list');
  }, [getCurrentSessions, selectedIndex, refresh]);

  // Handle keyboard input
  useInput((input, key) => {
    // Global quit
    if (input === 'q' && mode !== 'search' && mode !== 'rename' && mode !== 'sort-project' && mode !== 'db-size-alert' && mode !== 'confirm-purge' && mode !== 'storage' && mode !== 'storage-confirm') {
      exit();
      return;
    }

    // Mode-specific handling
    if (mode === 'confirm-delete') {
      if (input === 'y' || input === 'Y') {
        handleDelete();
      } else {
        setMode('list');
      }
      return;
    }

    if (mode === 'rename') {
      if (key.escape) {
        setMode('list');
        setRenameValue('');
        return;
      }
      if (key.return) {
        handleRename();
        return;
      }
      return;
    }

    if (mode === 'search') {
      if (key.escape) {
        setMode('list');
        setSearchQuery('');
        clearSearch();
        return;
      }
      if (key.return) {
        setMode('list');
        return;
      }
      return;
    }

    if (mode === 'sort-project') {
      if (key.escape || key.return) {
        setMode('list');
        return;
      }
      if (key.upArrow || input === 'k') {
        if (selectedIndex > 0) {
          moveProject(selectedIndex, selectedIndex - 1);
          setSelectedIndex(selectedIndex - 1);
        }
        return;
      }
      if (key.downArrow || input === 'j') {
        if (selectedIndex < projects.length - 1) {
          moveProject(selectedIndex, selectedIndex + 1);
          setSelectedIndex(selectedIndex + 1);
        }
        return;
      }
      return;
    }

    if (mode === 'db-size-alert') {
      if (input === 'y' || input === 'Y') {
        setMode('confirm-purge');
      } else {
        setMode('list');
      }
      return;
    }

    if (mode === 'confirm-purge') {
      if (input === 'y' || input === 'Y') {
        const result = purgeOldSessions(DEFAULT_PURGE_DAYS);
        const parts = [];
        if (result.sessionsDeleted > 0) {
          parts.push(`${result.sessionsDeleted} session${result.sessionsDeleted !== 1 ? 's' : ''}`);
        }
        if (result.backupsDeleted > 0) {
          parts.push(`${result.backupsDeleted} backup${result.backupsDeleted !== 1 ? 's' : ''}`);
        }
        setStatusMessage(`Purged ${parts.join(' and ')}`);
        refresh();
        setMode('list');
      } else {
        setMode('list');
      }
      return;
    }

    if (mode === 'storage') {
      if (key.escape || input === 'q') {
        setMode('list');
        return;
      }
      // Handle 1, 2, 3 keys for selecting purge option
      const optionIndex = parseInt(input, 10) - 1;
      if (optionIndex >= 0 && optionIndex < purgeOptions.length) {
        const option = purgeOptions[optionIndex];
        if (option && option.preview.sessionsToDelete > 0) {
          setSelectedPurgeOption(optionIndex);
          setMode('storage-confirm');
        }
      }
      return;
    }

    if (mode === 'storage-confirm') {
      if (input === 'y' || input === 'Y') {
        if (selectedPurgeOption !== null && purgeOptions[selectedPurgeOption]) {
          const days = purgeOptions[selectedPurgeOption].days;
          const result = purgeOldSessions(days);
          const parts = [];
          if (result.sessionsDeleted > 0) {
            parts.push(`${result.sessionsDeleted} session${result.sessionsDeleted !== 1 ? 's' : ''}`);
          }
          if (result.backupsDeleted > 0) {
            parts.push(`${result.backupsDeleted} backup${result.backupsDeleted !== 1 ? 's' : ''}`);
          }
          setStatusMessage(`Purged ${parts.join(' and ')}`);
          refresh();
          setSelectedPurgeOption(null);
          setMode('list');
        }
      } else {
        setSelectedPurgeOption(null);
        setMode('storage');
      }
      return;
    }

    // List mode
    if (input === '/') {
      setMode('search');
      return;
    }

    // Open storage management screen
    if (input === 'P') {
      // Load storage stats and purge previews
      const dbStats = getStats();
      const dbSizeVal = getDatabaseSize();
      const backupsSizeVal = getBackupsDirSize();
      setStorageStats({
        dbSize: dbSizeVal,
        backupsSize: backupsSizeVal,
        totalSize: dbSizeVal + backupsSizeVal,
        sessionCount: dbStats.sessionCount,
        messageCount: dbStats.messageCount,
      });
      setPurgeOptions([
        { days: 15, preview: getPurgePreview(15) },
        { days: 30, preview: getPurgePreview(30) },
        { days: 60, preview: getPurgePreview(60) },
      ]);
      setMode('storage');
      return;
    }

    // Back navigation (Escape or Backspace when in project-sessions)
    if ((key.escape || key.backspace || key.delete) && currentView === 'project-sessions') {
      handleBackToProjects();
      return;
    }

    if (input === 'r' && currentView !== 'projects') {
      const currentSessions = getCurrentSessions();
      if (currentSessions.length > 0) {
        const session = currentSessions[selectedIndex];
        setRenameValue(session?.customTitle || '');
        setMode('rename');
      }
      return;
    }

    if (input === 'R' && currentView !== 'projects') {
      handleClearRename();
      return;
    }

    // Tab navigation with left/right arrows
    if (key.leftArrow || input === 'h') {
      if (currentTab === 'projects') {
        setRenderKey(k => k + 1);
        setCurrentTab('global');
        setSelectedProjectPath(null);
      }
      return;
    }

    if (key.rightArrow || input === 'l') {
      if (currentTab === 'global') {
        setRenderKey(k => k + 1);
        setCurrentTab('projects');
      }
      return;
    }

    if (key.upArrow || input === 'k') {
      setSelectedIndex(prev => Math.max(0, prev - 1));
      return;
    }

    if (key.downArrow || input === 'j') {
      const maxIndex = currentView === 'projects'
        ? projects.length - 1
        : currentView === 'project-sessions'
          ? projectSessions.length - 1
          : sessions.length - 1;
      setSelectedIndex(prev => Math.min(maxIndex, prev + 1));
      return;
    }

    if (key.return) {
      if (currentView === 'projects') {
        handleEnterProject();
      } else {
        handleRestore();
      }
      return;
    }

    if (input === 'd' && currentView !== 'projects') {
      const currentSessions = getCurrentSessions();
      if (currentSessions.length > 0) {
        setMode('confirm-delete');
      }
      return;
    }

    if (input === 's') {
      if (currentView === 'projects') {
        // Enter sort mode for projects
        if (projects.length > 0) {
          setMode('sort-project');
          setStatusMessage('Sort mode: use ↑↓ to move, Enter to confirm');
        }
      } else {
        // Star/unstar session
        const currentSessions = getCurrentSessions();
        const session = currentSessions[selectedIndex];
        if (session) {
          const isNowFavorite = toggleFavorite(session.id);
          setStatusMessage(isNowFavorite ? '⭐ Added to favorites' : 'Removed from favorites');
        }
      }
      return;
    }
  });

  const handleSearchChange = useCallback((value: string) => {
    setSearchQuery(value);
    setSelectedIndex(0);
  }, []);

  if (loading && sessions.length === 0) {
    return (
      <Box padding={1}>
        <Spinner type="dots" />
        <Text> Loading sessions...</Text>
      </Box>
    );
  }

  const currentSessions = getCurrentSessions();
  const selectedSession = currentView !== 'projects' ? currentSessions[selectedIndex] || null : null;
  const selectedProject = currentView === 'projects' ? projects[selectedIndex] || null : null;

  // Render storage screen if in storage mode
  if ((mode === 'storage' || mode === 'storage-confirm') && storageStats) {
    return (
      <Box key={renderKey} flexDirection="column" padding={1}>
        <StorageScreen
          stats={storageStats}
          purgeOptions={purgeOptions}
          selectedOption={selectedPurgeOption}
          mode={mode === 'storage-confirm' ? 'confirm' : 'view'}
        />
      </Box>
    );
  }

  return (
    <Box key={renderKey} flexDirection="column" padding={1}>
      <Header embeddingsReady={embeddingsReady} projectFilter={selectedProjectPath} />

      {/* Search row - always render to maintain consistent height */}
      {currentTab === 'global' ? (
        <SearchInput
          value={searchQuery}
          onChange={handleSearchChange}
          isFocused={mode === 'search'}
        />
      ) : currentView === 'project-sessions' && selectedProjectPath ? (
        <Box>
          <Text dimColor>Projects → </Text>
          <Text color="blue">{basename(selectedProjectPath)}</Text>
        </Box>
      ) : (
        <Box>
          <Text dimColor>Browse projects below</Text>
        </Box>
      )}

      {currentView === 'projects' ? (
        <ProjectList
          projects={projects}
          selectedIndex={selectedIndex}
          onSelect={setSelectedIndex}
        />
      ) : (
        <SessionList
          sessions={currentSessions}
          selectedIndex={selectedIndex}
          onSelect={setSelectedIndex}
        />
      )}

      {selectedSession && <Preview session={selectedSession} />}

      {selectedProject && (
        <Box
          flexDirection="column"
          borderStyle="round"
          borderColor="gray"
          paddingX={1}
          paddingY={0}
          marginTop={1}
        >
          <Box>
            <Text bold>Project Preview</Text>
            {selectedProject.sortOrder !== null && <Text dimColor> (#{selectedProject.sortOrder + 1})</Text>}
          </Box>
          <Text color="blue">📁 {selectedProject.path}</Text>
          <Text dimColor>
            {selectedProject.sessionCount} session{selectedProject.sessionCount !== 1 ? 's' : ''} • {selectedProject.totalMessages} messages
          </Text>
        </Box>
      )}

      {/* Footer - Controls */}
      <Box marginTop={1}>
        {mode === 'db-size-alert' ? (
          <Box flexDirection="column">
            <Text color="yellow" bold>
              ⚠ Storage size: {formatBytes(dbSize)} (exceeds 5GB)
            </Text>
            <Text color="yellow">
              Purge {purgePreview?.sessionsToDelete} sessions older than {DEFAULT_PURGE_DAYS} days? [y/n]
            </Text>
            {purgePreview && purgePreview.backupFilesToDelete > 0 && (
              <Text dimColor>  ({purgePreview.backupFilesToDelete} backup files, ~{formatBytes(purgePreview.backupBytesToFree)})</Text>
            )}
            <Text dimColor>(Starred sessions will be kept)</Text>
          </Box>
        ) : mode === 'confirm-purge' ? (
          <Box flexDirection="column">
            <Text color="red" bold>Confirm purge:</Text>
            <Text>  {purgePreview?.sessionsToDelete} sessions ({purgePreview?.messagesInvolved} messages)</Text>
            {purgePreview && purgePreview.backupFilesToDelete > 0 && (
              <Text>  {purgePreview.backupFilesToDelete} backup files (~{formatBytes(purgePreview.backupBytesToFree)})</Text>
            )}
            <Text>  Range: {purgePreview?.oldestSessionDate} to {purgePreview?.newestSessionDate}</Text>
            <Text color="red">This cannot be undone. Proceed? [y/n]</Text>
          </Box>
        ) : mode === 'confirm-delete' ? (
          <Text color="yellow">
            Delete "{selectedSession?.customTitle || selectedSession?.title}"? [y/n]
          </Text>
        ) : mode === 'rename' ? (
          <Box>
            <Text color="magenta">Rename: </Text>
            <TextInput
              value={renameValue}
              onChange={setRenameValue}
              placeholder="Enter new name..."
            />
            <Text dimColor>  [Enter] Save  [Esc] Cancel</Text>
          </Box>
        ) : mode === 'sort-project' ? (
          <Text color="cyan">
            Sort mode: [↑↓] Move project  [Enter/Esc] Done
          </Text>
        ) : statusMessage ? (
          <Text color="green">{statusMessage}</Text>
        ) : currentView === 'projects' ? (
          <Text dimColor>
            [↑↓] Navigate  [Enter] Open  [s] Sort  [P] Storage  [←→] Tabs  [q] Quit
          </Text>
        ) : currentView === 'project-sessions' ? (
          <Text dimColor>
            [↑↓] Navigate  [Enter] Resume  [s] Star  [Esc] Back  [r] Rename  [d] Delete  [P] Storage  [q] Quit
          </Text>
        ) : (
          <Text dimColor>
            [↑↓] Navigate  [Enter] Resume  [s] Star  [r] Rename  [d] Delete  [/] Search  [P] Storage  [q] Quit
          </Text>
        )}
      </Box>

      {/* Tab bar at bottom */}
      <Box marginTop={1}>
        <Text
          backgroundColor={currentTab === 'global' ? 'green' : undefined}
          color={currentTab === 'global' ? 'white' : undefined}
          bold={currentTab === 'global'}
          dimColor={currentTab !== 'global'}
        >
          {currentTab === 'global' ? ' Global ' : 'Global'}
        </Text>
        <Text> </Text>
        <Text
          backgroundColor={currentTab === 'projects' ? 'magenta' : undefined}
          color={currentTab === 'projects' ? 'white' : undefined}
          bold={currentTab === 'projects'}
          dimColor={currentTab !== 'projects'}
        >
          {currentTab === 'projects' ? ' Projects ' : 'Projects'}
        </Text>
        <Text dimColor>  [←→] switch</Text>
      </Box>
    </Box>
  );
};
