import React from 'react';
import { Box, Text } from 'ink';
import { basename } from 'path';

interface HeaderProps {
  embeddingsReady: boolean;
  projectFilter?: string | null;
}

export const Header: React.FC<HeaderProps> = ({ embeddingsReady, projectFilter }) => {
  return (
    <Box marginBottom={1} justifyContent="space-between">
      <Box>
        <Text bold color="cyan">cmem</Text>
        {projectFilter && (
          <Text color="yellow"> 📁 {basename(projectFilter)}</Text>
        )}
        {!embeddingsReady && (
          <Text color="yellow" dimColor> (loading model...)</Text>
        )}
      </Box>
      <Text dimColor>[q] quit</Text>
    </Box>
  );
};
