import chalk from 'chalk';
import chokidar from 'chokidar';
import { statSync, existsSync, readFileSync, readdirSync } from 'fs';
import { join, dirname, basename } from 'path';
import { CLAUDE_DIR, backupSessionFile } from '../utils/config.js';
import { parseSessionFile, generateSummary, ParsedMessage, extractSessionMetadata, isAutomatedByContent } from '../parser/index.js';
import {
  createSession,
  getSessionBySourceFile,
  updateSession,
  needsReembedding,
  updateEmbeddingState,
  getStats,
} from '../db/sessions.js';
import { storeEmbedding } from '../db/vectors.js';
import { getEmbedding, createEmbeddingText, initializeEmbeddings, isReady } from '../embeddings/index.js';
import { generateTitle } from '../utils/format.js';

// Spinner animation frames
const spinnerFrames = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];

class Spinner {
  private interval: NodeJS.Timeout | null = null;
  private frameIndex = 0;
  private message: string;

  constructor(message: string) {
    this.message = message;
  }

  start(): void {
    process.stdout.write(`  ${spinnerFrames[0]} ${this.message}`);
    this.interval = setInterval(() => {
      this.frameIndex = (this.frameIndex + 1) % spinnerFrames.length;
      process.stdout.write(`\r  ${chalk.cyan(spinnerFrames[this.frameIndex])} ${this.message}`);
    }, 80);
  }

  update(message: string): void {
    this.message = message;
    process.stdout.write(`\r  ${chalk.cyan(spinnerFrames[this.frameIndex])} ${this.message}                              `);
  }

  succeed(message?: string): void {
    this.stop();
    console.log(`\r  ${chalk.green('✓')} ${message || this.message}                              `);
  }

  fail(message?: string): void {
    this.stop();
    console.log(`\r  ${chalk.red('✗')} ${message || this.message}                              `);
  }

  stop(): void {
    if (this.interval) {
      clearInterval(this.interval);
      this.interval = null;
    }
  }
}

interface SessionIndexEntry {
  sessionId: string;
  projectPath: string;
}

interface WatchOptions {
  verbose?: boolean;
  embedThreshold?: number;
}

// Debounce map to prevent rapid re-processing
const processingDebounce = new Map<string, NodeJS.Timeout>();
const DEBOUNCE_MS = 2000; // Wait 2 seconds after last change before processing

export async function watchCommand(options: WatchOptions): Promise<void> {
  const verbose = options.verbose ?? false;
  const embedThreshold = options.embedThreshold ?? 500;

  console.log(chalk.cyan('🔍 cmem watch - Monitoring Claude Code sessions\n'));

  // Initialize embeddings (downloads model if needed)
  const modelSpinner = new Spinner('Initializing embedding model...');
  modelSpinner.start();

  try {
    await initializeEmbeddings((progress) => {
      if (progress.status === 'downloading' && progress.progress !== undefined) {
        const fileName = progress.file ? progress.file.split('/').pop() : 'model';
        modelSpinner.update(`Downloading ${fileName}... ${Math.round(progress.progress)}%`);
      } else if (progress.status === 'loading') {
        modelSpinner.update('Loading model...');
      }
    });
    modelSpinner.succeed('Embedding model ready');
  } catch (err) {
    modelSpinner.fail('Could not initialize embeddings');
    console.log(chalk.yellow('  Sessions will be saved but not vectorized.\n'));
  }

  const embeddingsReady = isReady();
  console.log('');

  // First, do an initial scan to find and index all existing sessions
  const scanSpinner = new Spinner('Scanning for existing sessions...');
  scanSpinner.start();

  const existingFiles = findAllSessionFiles(CLAUDE_DIR);
  const totalFiles = existingFiles.length;

  // Get current stats to see how many are already indexed
  const statsBefore = getStats();
  const alreadyIndexed = statsBefore.sessionCount;
  const needsIndexing = totalFiles - alreadyIndexed;

  if (totalFiles === 0) {
    scanSpinner.succeed('No Claude Code sessions found yet');
  } else if (needsIndexing <= 0) {
    scanSpinner.succeed(`Found ${totalFiles} sessions (all indexed)`);
  } else {
    scanSpinner.update(`Found ${totalFiles} sessions, indexing ${needsIndexing} new...`);

    let processed = 0;
    let newlyIndexed = 0;

    for (const filePath of existingFiles) {
      processed++;
      // Force metadata update during initial scan to migrate existing sessions
      const wasNew = await processSessionFile(filePath, embeddingsReady, embedThreshold, false, true);
      if (wasNew) newlyIndexed++;

      // Update spinner with progress
      const percent = Math.round((processed / totalFiles) * 100);
      scanSpinner.update(`Indexing sessions... ${percent}% (${processed}/${totalFiles})`);
    }

    scanSpinner.succeed(`Indexed ${totalFiles} sessions (${newlyIndexed} new, ${totalFiles - newlyIndexed} updated)`);
  }

  console.log('');
  console.log(chalk.dim(`Watching: ${CLAUDE_DIR}`));
  console.log(chalk.dim(`Embed threshold: ${embedThreshold} chars\n`));

  // Now watch for changes (ignore initial since we already processed)
  const watcher = chokidar.watch(CLAUDE_DIR, {
    persistent: true,
    ignoreInitial: true, // We already processed existing files above
    depth: 10,
    awaitWriteFinish: {
      stabilityThreshold: 1000,
      pollInterval: 100,
    },
  });

  watcher.on('add', (filePath) => {
    if (!filePath.endsWith('.jsonl')) return;
    if (filePath.includes('/subagents/')) {
      if (verbose) console.log(chalk.dim(`[skip agent] ${filePath}`));
      return;
    }
    if (verbose) console.log(chalk.dim(`[new] ${filePath}`));
    debouncedProcess(filePath, embeddingsReady, embedThreshold, verbose);
  });

  watcher.on('change', (filePath) => {
    if (!filePath.endsWith('.jsonl')) return;
    if (filePath.includes('/subagents/')) {
      if (verbose) console.log(chalk.dim(`[skip agent] ${filePath}`));
      return;
    }
    if (verbose) console.log(chalk.dim(`[changed] ${filePath}`));
    debouncedProcess(filePath, embeddingsReady, embedThreshold, verbose);
  });

  watcher.on('error', (error) => {
    console.error(chalk.red('Watcher error:'), error);
  });

  watcher.on('ready', () => {
    console.log(chalk.green('✓ Watching for session changes...'));
    console.log(chalk.dim('Press Ctrl+C to stop\n'));
  });

  process.on('SIGINT', () => {
    console.log(chalk.dim('\nShutting down watcher...'));
    watcher.close();
    process.exit(0);
  });

  process.on('SIGTERM', () => {
    watcher.close();
    process.exit(0);
  });
}

/**
 * Find all .jsonl session files in the Claude directory
 */
function findAllSessionFiles(dir: string): string[] {
  const files: string[] = [];

  if (!existsSync(dir)) return files;

  function scanDir(currentDir: string, depth: number = 0): void {
    if (depth > 10) return; // Max depth

    try {
      const entries = readdirSync(currentDir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = join(currentDir, entry.name);

        if (entry.isDirectory()) {
          // Skip subagents folder
          if (entry.name === 'subagents') continue;
          scanDir(fullPath, depth + 1);
        } else if (entry.isFile() && entry.name.endsWith('.jsonl')) {
          files.push(fullPath);
        }
      }
    } catch {
      // Ignore permission errors
    }
  }

  scanDir(dir);
  return files;
}

function debouncedProcess(
  filePath: string,
  embeddingsReady: boolean,
  embedThreshold: number,
  verbose: boolean
): void {
  // Clear any existing debounce timer for this file
  const existing = processingDebounce.get(filePath);
  if (existing) {
    clearTimeout(existing);
  }

  // Set new debounce timer
  const timer = setTimeout(async () => {
    processingDebounce.delete(filePath);
    await processSessionFile(filePath, embeddingsReady, embedThreshold, verbose);
  }, DEBOUNCE_MS);

  processingDebounce.set(filePath, timer);
}

async function processSessionFile(
  filePath: string,
  embeddingsReady: boolean,
  embedThreshold: number,
  verbose: boolean,
  forceMetadataUpdate = false
): Promise<boolean> {
  try {
    // Parse the session file
    const messages = parseSessionFile(filePath);

    if (messages.length === 0) {
      if (verbose) console.log(chalk.dim(`  Skipping empty session: ${filePath}`));
      return false;
    }

    // Get file stats
    const stats = statSync(filePath);
    const fileMtime = stats.mtime.toISOString();

    // Check if we already have this session
    const existingSession = getSessionBySourceFile(filePath);

    // Get session ID from filename
    const sessionId_from_file = basename(filePath, '.jsonl');

    // Load agent messages for this session (for embeddings)
    const agentMessages = loadSubagentMessages(dirname(filePath), sessionId_from_file);
    const allMessages = [...messages, ...agentMessages];

    // Calculate content length for embedding decisions (including agent messages)
    const contentLength = allMessages.reduce((sum, m) => sum + m.content.length, 0);

    // Generate title from first user message
    const firstUserMsg = messages.find(m => m.role === 'user');
    const title = firstUserMsg ? generateTitle(firstUserMsg.content) : 'Untitled Session';

    // Generate summary
    const summary = generateSummary(messages);

    // Build raw data for storage
    const rawData = JSON.stringify({ filePath, messages, mtime: fileMtime });

    // Get project path from sessions-index.json
    const projectPath = getProjectPathFromIndex(filePath, sessionId_from_file);

    // Extract metadata (isSidechain, agentId, isMeta) from JSONL
    const metadata = extractSessionMetadata(filePath);
    // Mark as automated if: JSONL metadata says so, OR title matches automated patterns
    const isAutomated = metadata.isSidechain || metadata.isMeta || isAutomatedByContent(title);

    let sessionId: string;
    let isNew = false;

    if (existingSession) {
      // Update existing session
      sessionId = existingSession.id;

      // Update metadata if it needs to be set (for sessions created before metadata tracking)
      // forceMetadataUpdate is true during initial scan to migrate existing sessions
      const needsMetadataUpdate = forceMetadataUpdate ||
        (!existingSession.isSidechain && !existingSession.isAutomated && isAutomated);

      // Update if content has changed OR metadata needs updating OR projectPath is missing
      const needsProjectPathUpdate = !existingSession.projectPath && projectPath;
      if (existingSession.messageCount !== messages.length || needsMetadataUpdate || needsProjectPathUpdate) {
        updateSession(sessionId, {
          title,
          summary,
          rawData,
          messages,
          isSidechain: metadata.isSidechain,
          isAutomated,
          projectPath: projectPath || undefined,
        });

        if (verbose) {
          const automatedTag = isAutomated ? chalk.dim(' [auto]') : '';
          console.log(chalk.blue(`↻ Updated: ${title} (${messages.length} msgs)${automatedTag}`));
        }
      }
    } else {
      // Create new session
      isNew = true;
      sessionId = createSession({
        title,
        summary,
        projectPath,
        sourceFile: filePath,
        rawData,
        messages,
        isSidechain: metadata.isSidechain,
        isAutomated,
      });

      if (verbose) {
        const automatedTag = isAutomated ? chalk.dim(' [auto]') : '';
        console.log(chalk.green(`✓ Saved: ${title} (${messages.length} msgs)${automatedTag}`));
      }
    }

    // Handle embedding (include agent messages for better search)
    if (embeddingsReady) {
      const shouldEmbed = needsReembedding(sessionId, contentLength, embedThreshold);

      if (shouldEmbed) {
        try {
          // Use all messages including agents for richer embeddings
          const embeddingText = createEmbeddingText(title, summary, allMessages);
          const embedding = await getEmbedding(embeddingText);
          storeEmbedding(sessionId, embedding);
          updateEmbeddingState(sessionId, contentLength, fileMtime);

          if (verbose) {
            const agentCount = agentMessages.length;
            const agentInfo = agentCount > 0 ? ` (+${agentCount} agent msgs)` : '';
            console.log(chalk.dim(`  Embedded: ${title}${agentInfo}`));
          }
        } catch (err) {
          if (verbose) {
            console.log(chalk.yellow(`  Failed to embed: ${title}`));
            console.log(chalk.dim(`    ${err}`));
          }
        }
      }
    }

    // Backup the JSONL file to cmem's storage (conversations never lost)
    const backedUp = backupSessionFile(filePath);
    if (verbose && backedUp) {
      console.log(chalk.dim(`  Backed up: ${basename(filePath)}`));
    }

    return isNew;
  } catch (err) {
    if (verbose) console.log(chalk.red(`Error processing ${filePath}:`), err);
    return false;
  }
}

/**
 * Load messages from all subagent sessions for a parent session
 */
function loadSubagentMessages(projectDirPath: string, parentSessionId: string): ParsedMessage[] {
  const subagentsDir = join(projectDirPath, parentSessionId, 'subagents');
  if (!existsSync(subagentsDir)) return [];

  const messages: ParsedMessage[] = [];

  try {
    const agentFiles = readdirSync(subagentsDir).filter(f => f.endsWith('.jsonl'));
    for (const agentFile of agentFiles) {
      const agentPath = join(subagentsDir, agentFile);
      const agentMessages = parseSessionFile(agentPath);
      messages.push(...agentMessages);
    }
  } catch {
    // Ignore errors reading subagent files
  }

  return messages;
}

/**
 * Get project path from sessions-index.json
 */
function getProjectPathFromIndex(filePath: string, sessionId: string): string | null {
  const projectDir = dirname(filePath);
  const indexPath = join(projectDir, 'sessions-index.json');

  if (!existsSync(indexPath)) return null;

  try {
    const content = readFileSync(indexPath, 'utf-8');
    const index = JSON.parse(content) as { entries: SessionIndexEntry[] };
    const entry = index.entries.find(e => e.sessionId === sessionId);
    return entry?.projectPath || null;
  } catch {
    return null;
  }
}
