import React from 'react';
import { Box, Text } from 'ink';
import { basename } from 'path';
import type { SessionWithFavorite } from '../hooks/useSessions.js';
import { formatTimeAgo, truncate } from '../../utils/format.js';

interface SessionListProps {
  sessions: SessionWithFavorite[];
  selectedIndex: number;
  onSelect: (index: number) => void;
}

export const SessionList: React.FC<SessionListProps> = ({
  sessions,
  selectedIndex,
}) => {
  if (sessions.length === 0) {
    return (
      <Box
        flexDirection="column"
        borderStyle="round"
        borderColor="gray"
        paddingX={1}
        paddingY={0}
      >
        <Text bold>Sessions</Text>
        <Text dimColor>No sessions found</Text>
        <Text dimColor>Run: cmem save --latest</Text>
      </Box>
    );
  }

  // Show max 8 sessions, centered around selected
  const visibleCount = 8;
  let startIndex = Math.max(0, selectedIndex - Math.floor(visibleCount / 2));
  const endIndex = Math.min(sessions.length, startIndex + visibleCount);
  if (endIndex - startIndex < visibleCount) {
    startIndex = Math.max(0, endIndex - visibleCount);
  }

  const visibleSessions = sessions.slice(startIndex, endIndex);

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor="gray"
      paddingX={1}
      paddingY={0}
    >
      <Text bold>Sessions ({sessions.length})</Text>
      {visibleSessions.map((session, i) => {
        const actualIndex = startIndex + i;
        const isSelected = actualIndex === selectedIndex;

        return (
          <SessionItem
            key={session.id}
            session={session}
            isSelected={isSelected}
          />
        );
      })}
      {sessions.length > visibleCount && (
        <Text dimColor>
          {startIndex > 0 ? '↑ more above' : ''}
          {startIndex > 0 && endIndex < sessions.length ? ' | ' : ''}
          {endIndex < sessions.length ? '↓ more below' : ''}
        </Text>
      )}
    </Box>
  );
};

interface SessionItemProps {
  session: SessionWithFavorite;
  isSelected: boolean;
}

const SessionItem: React.FC<SessionItemProps> = ({ session, isSelected }) => {
  const hasCustomTitle = !!session.customTitle;
  const displayTitle = truncate(session.customTitle || session.title, 38);
  const folderName = session.projectPath ? truncate(basename(session.projectPath), 38) : '';
  const msgs = String(session.messageCount).padStart(3);
  const updated = formatTimeAgo(session.updatedAt);

  // Determine title color: cyan if selected, magenta if renamed, yellow if favorite, undefined otherwise
  const getTitleColor = () => {
    if (isSelected) return 'cyan';
    if (session.isFavorite) return 'yellow';
    if (hasCustomTitle) return 'magenta';
    return undefined;
  };

  return (
    <Box>
      <Text color={isSelected ? 'cyan' : undefined}>
        {isSelected ? '▸ ' : '  '}
      </Text>
      <Text color="yellow">{session.isFavorite ? '⭐' : '  '}</Text>
      <Text bold={isSelected} color={getTitleColor()} wrap="truncate">
        {displayTitle.padEnd(38)}
      </Text>
      <Text color="blue"> {folderName.padEnd(38)}</Text>
      <Text dimColor> {msgs} </Text>
      <Text dimColor>{updated.padStart(8)}</Text>
    </Box>
  );
};
