import { getDatabase } from './index.js';
import type { Session } from './sessions.js';

/**
 * Store an embedding for a session
 */
export function storeEmbedding(sessionId: string, embedding: number[]): void {
  const db = getDatabase();

  // sqlite-vec expects JSON array format
  const embeddingJson = JSON.stringify(embedding);

  db.prepare(`
    INSERT OR REPLACE INTO session_embeddings (session_id, embedding)
    VALUES (?, ?)
  `).run(sessionId, embeddingJson);
}

/**
 * Search for similar sessions using vector similarity
 */
export function searchSimilar(queryEmbedding: number[], limit = 10): Array<{ sessionId: string; distance: number }> {
  const db = getDatabase();

  const embeddingJson = JSON.stringify(queryEmbedding);

  // Use vec_distance_L2 for Euclidean distance (lower = more similar)
  const rows = db.prepare(`
    SELECT session_id as sessionId, vec_distance_L2(embedding, ?) as distance
    FROM session_embeddings
    ORDER BY distance ASC
    LIMIT ?
  `).all(embeddingJson, limit) as Array<{ sessionId: string; distance: number }>;

  return rows;
}

/**
 * Search sessions and return full session objects
 */
export function searchSessions(queryEmbedding: number[], limit = 10): Session[] {
  const db = getDatabase();

  const embeddingJson = JSON.stringify(queryEmbedding);

  const rows = db.prepare(`
    SELECT s.id, s.title, s.summary, s.created_at as createdAt, s.updated_at as updatedAt,
           s.message_count as messageCount, s.project_path as projectPath, s.raw_data as rawData,
           vec_distance_L2(e.embedding, ?) as distance
    FROM session_embeddings e
    JOIN sessions s ON e.session_id = s.id
    ORDER BY distance ASC
    LIMIT ?
  `).all(embeddingJson, limit) as Session[];

  return rows;
}

/**
 * Delete embedding for a session
 */
export function deleteEmbedding(sessionId: string): void {
  const db = getDatabase();
  db.prepare('DELETE FROM session_embeddings WHERE session_id = ?').run(sessionId);
}

/**
 * Check if session has an embedding
 */
export function hasEmbedding(sessionId: string): boolean {
  const db = getDatabase();
  const row = db.prepare('SELECT 1 FROM session_embeddings WHERE session_id = ? LIMIT 1').get(sessionId);
  return !!row;
}
