import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from '@modelcontextprotocol/sdk/types.js';
import {
  listSessions,
  getSession,
  getSessionMessages,
  getSessionBySourceFile,
  getSessionByIdPrefix,
} from '../db/sessions.js';
import { searchSessions } from '../db/vectors.js';
import { getEmbedding, initializeEmbeddings, isReady } from '../embeddings/index.js';
import { formatTimeAgo, truncate } from '../utils/format.js';
import { runClaudePrompt, isClaudeCliAvailable } from '../utils/claude-cli.js';
import {
  getLesson,
  getLessonsByProject,
  searchLessonsByEmbedding,
  getLessonStats,
} from '../db/lessons.js';
import { lessonManager } from '../learning/LessonManager.js';
import type { LessonCategory, CreateLessonInput } from '../learning/types.js';
import { VALID_CATEGORIES } from '../learning/types.js';

/**
 * Create and configure the MCP server
 */
export function createMcpServer(): Server {
  const server = new Server(
    {
      name: 'cmem',
      version: '0.1.0',
    },
    {
      capabilities: {
        tools: {},
      },
    }
  );

  // List available tools
  server.setRequestHandler(ListToolsRequestSchema, async () => {
    return {
      tools: [
        {
          name: 'search_sessions',
          description:
            'Semantic search across all saved Claude Code conversation sessions. Use this to find past conversations about specific topics, projects, or problems. Returns matching sessions ranked by relevance.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              query: {
                type: 'string',
                description:
                  'Natural language search query. Examples: "React hooks discussion", "database migration", "authentication implementation"',
              },
              limit: {
                type: 'number',
                description: 'Maximum number of results to return (default: 5)',
              },
            },
            required: ['query'],
          },
        },
        {
          name: 'list_sessions',
          description:
            'List all saved Claude Code conversation sessions, ordered by most recently updated. Use this to browse available sessions or find recent conversations.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              limit: {
                type: 'number',
                description: 'Maximum number of sessions to return (default: 10)',
              },
            },
          },
        },
        {
          name: 'get_session',
          description:
            'Get detailed information about a specific conversation session, including its full message history. Use this after finding a session via search or list.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              sessionId: {
                type: 'string',
                description: 'The session ID to retrieve',
              },
              includeMessages: {
                type: 'boolean',
                description: 'Whether to include the full message history (default: true)',
              },
              messageLimit: {
                type: 'number',
                description: 'Maximum number of messages to include (default: 50, from most recent)',
              },
            },
            required: ['sessionId'],
          },
        },
        {
          name: 'get_session_context',
          description:
            'Get a formatted context summary from a past session that can be used to continue or reference that conversation. Returns key information and recent messages in a readable format.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              sessionId: {
                type: 'string',
                description: 'The session ID to get context from',
              },
              messageCount: {
                type: 'number',
                description: 'Number of recent messages to include (default: 10)',
              },
            },
            required: ['sessionId'],
          },
        },
        {
          name: 'search_and_summarize',
          description:
            'Search past Claude Code sessions and get an AI-generated summary tailored to your specific question. This spawns a separate Claude instance to read and synthesize the relevant sessions, keeping your main context clean. Use this when you need insights from past conversations.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              query: {
                type: 'string',
                description:
                  'Your question or topic to search for. Examples: "What did we decide about the database schema?", "How did we implement authentication?", "What was the bug fix for the login issue?"',
              },
              sessionLimit: {
                type: 'number',
                description: 'Maximum number of sessions to analyze (default: 3)',
              },
              model: {
                type: 'string',
                enum: ['haiku', 'sonnet', 'opus'],
                description: 'Model to use for summarization (default: haiku for speed)',
              },
            },
            required: ['query'],
          },
        },
        // ==================== LESSON TOOLS ====================
        {
          name: 'search_lessons',
          description:
            'Search learned lessons for a project using semantic search. Returns lessons that match the query context.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              query: {
                type: 'string',
                description: 'Search query describing what you want to find',
              },
              projectPath: {
                type: 'string',
                description: 'Project path to search lessons for (defaults to current directory)',
              },
              limit: {
                type: 'number',
                description: 'Maximum number of results (default: 5)',
              },
            },
            required: ['query'],
          },
        },
        {
          name: 'get_lesson',
          description:
            'Get details of a specific learned lesson by ID.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              lessonId: {
                type: 'string',
                description: 'The lesson ID to retrieve',
              },
            },
            required: ['lessonId'],
          },
        },
        {
          name: 'save_lesson',
          description:
            'Manually save a new lesson. Use this when you learn something important about a project that should be remembered.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              projectPath: {
                type: 'string',
                description: 'Project path this lesson applies to',
              },
              category: {
                type: 'string',
                enum: VALID_CATEGORIES,
                description: 'Category of the lesson',
              },
              title: {
                type: 'string',
                description: 'Short title (max 60 chars)',
              },
              triggerContext: {
                type: 'string',
                description: 'When this lesson should be surfaced',
              },
              insight: {
                type: 'string',
                description: 'The actual knowledge (specific, actionable)',
              },
              reasoning: {
                type: 'string',
                description: 'Why this is true (optional)',
              },
            },
            required: ['projectPath', 'category', 'title', 'triggerContext', 'insight'],
          },
        },
        {
          name: 'validate_lesson',
          description:
            'Mark a lesson as helpful/correct. Boosts its confidence score.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              lessonId: {
                type: 'string',
                description: 'The lesson ID to validate',
              },
              comment: {
                type: 'string',
                description: 'Optional comment about why it was helpful',
              },
            },
            required: ['lessonId'],
          },
        },
        {
          name: 'reject_lesson',
          description:
            'Mark a lesson as unhelpful/incorrect. Reduces its confidence score.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              lessonId: {
                type: 'string',
                description: 'The lesson ID to reject',
              },
              comment: {
                type: 'string',
                description: 'Optional comment about why it was wrong',
              },
            },
            required: ['lessonId'],
          },
        },
        {
          name: 'list_lessons',
          description:
            'List all lessons for a project.',
          inputSchema: {
            type: 'object' as const,
            properties: {
              projectPath: {
                type: 'string',
                description: 'Project path to list lessons for',
              },
              category: {
                type: 'string',
                enum: VALID_CATEGORIES,
                description: 'Filter by category',
              },
              includeArchived: {
                type: 'boolean',
                description: 'Include archived lessons (default: false)',
              },
              limit: {
                type: 'number',
                description: 'Maximum number of results (default: 20)',
              },
            },
            required: ['projectPath'],
          },
        },
      ],
    };
  });

  // Handle tool calls
  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;

    try {
      switch (name) {
        case 'search_sessions':
          return await handleSearchSessions(args as { query: string; limit?: number });

        case 'list_sessions':
          return await handleListSessions(args as { limit?: number });

        case 'get_session':
          return await handleGetSession(
            args as { sessionId: string; includeMessages?: boolean; messageLimit?: number }
          );

        case 'get_session_context':
          return await handleGetSessionContext(
            args as { sessionId: string; messageCount?: number }
          );

        case 'search_and_summarize':
          return await handleSearchAndSummarize(
            args as { query: string; sessionLimit?: number; model?: 'haiku' | 'sonnet' | 'opus' }
          );

        // ==================== LESSON HANDLERS ====================
        case 'search_lessons':
          return await handleSearchLessons(
            args as { query: string; projectPath?: string; limit?: number }
          );

        case 'get_lesson':
          return await handleGetLesson(args as { lessonId: string });

        case 'save_lesson':
          return await handleSaveLesson(
            args as {
              projectPath: string;
              category: LessonCategory;
              title: string;
              triggerContext: string;
              insight: string;
              reasoning?: string;
            }
          );

        case 'validate_lesson':
          return await handleValidateLesson(
            args as { lessonId: string; comment?: string }
          );

        case 'reject_lesson':
          return await handleRejectLesson(
            args as { lessonId: string; comment?: string }
          );

        case 'list_lessons':
          return await handleListLessons(
            args as {
              projectPath: string;
              category?: LessonCategory;
              includeArchived?: boolean;
              limit?: number;
            }
          );

        default:
          return {
            content: [{ type: 'text', text: `Unknown tool: ${name}` }],
            isError: true,
          };
      }
    } catch (error) {
      return {
        content: [{ type: 'text', text: `Error: ${String(error)}` }],
        isError: true,
      };
    }
  });

  return server;
}

async function handleSearchSessions(args: { query: string; limit?: number }) {
  const { query, limit = 5 } = args;

  // Initialize embeddings if needed
  if (!isReady()) {
    try {
      await initializeEmbeddings();
    } catch {
      // Fall back to simple text search
      const allSessions = listSessions(100);
      const queryLower = query.toLowerCase();
      const filtered = allSessions
        .filter(
          (s) =>
            s.title.toLowerCase().includes(queryLower) ||
            (s.summary && s.summary.toLowerCase().includes(queryLower))
        )
        .slice(0, limit);

      return {
        content: [
          {
            type: 'text',
            text: formatSessionList(filtered, `Text search results for "${query}" (embeddings unavailable)`),
          },
        ],
      };
    }
  }

  // Semantic search
  const queryEmbedding = await getEmbedding(query);
  const results = searchSessions(queryEmbedding, limit);

  return {
    content: [
      {
        type: 'text',
        text: formatSessionList(results, `Semantic search results for "${query}"`),
      },
    ],
  };
}

async function handleListSessions(args: { limit?: number }) {
  const { limit = 10 } = args;
  const sessions = listSessions(limit);

  return {
    content: [
      {
        type: 'text',
        text: formatSessionList(sessions, 'Recent sessions'),
      },
    ],
  };
}

async function handleGetSession(args: {
  sessionId: string;
  includeMessages?: boolean;
  messageLimit?: number;
}) {
  const { sessionId, includeMessages = true, messageLimit = 50 } = args;

  // Support partial ID matching - try exact match first, then prefix match
  let session = getSession(sessionId) || getSessionByIdPrefix(sessionId);

  if (!session) {
    return {
      content: [{ type: 'text', text: `Session not found: ${sessionId}` }],
      isError: true,
    };
  }

  const lines: string[] = [
    `# Session: ${session.title}`,
    '',
    `**ID:** ${session.id}`,
    `**Created:** ${session.createdAt}`,
    `**Updated:** ${session.updatedAt} (${formatTimeAgo(session.updatedAt)})`,
    `**Messages:** ${session.messageCount}`,
  ];

  if (session.projectPath) {
    lines.push(`**Project:** ${session.projectPath}`);
  }

  if (session.summary) {
    lines.push('', '## Summary', session.summary);
  }

  if (includeMessages) {
    const messages = getSessionMessages(session.id);
    const recentMessages = messages.slice(-messageLimit);

    lines.push('', '## Messages', '');

    for (const msg of recentMessages) {
      lines.push(`### ${msg.role === 'user' ? 'User' : 'Assistant'}`);
      lines.push(msg.content);
      lines.push('');
    }

    if (messages.length > messageLimit) {
      lines.push(`_...${messages.length - messageLimit} earlier messages omitted_`);
    }
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }],
  };
}

async function handleGetSessionContext(args: { sessionId: string; messageCount?: number }) {
  const { sessionId, messageCount = 10 } = args;

  // Support partial ID matching - try exact match first, then prefix match
  let session = getSession(sessionId) || getSessionByIdPrefix(sessionId);

  if (!session) {
    return {
      content: [{ type: 'text', text: `Session not found: ${sessionId}` }],
      isError: true,
    };
  }

  const messages = getSessionMessages(session.id);
  const recentMessages = messages.slice(-messageCount);

  const lines: string[] = [
    '# Context from Previous Session',
    '',
    `**Topic:** ${session.title}`,
  ];

  if (session.projectPath) {
    lines.push(`**Project:** ${session.projectPath}`);
  }

  if (session.summary) {
    lines.push('', '## Summary', session.summary);
  }

  lines.push(
    '',
    '## Recent Conversation',
    `_Last ${recentMessages.length} of ${messages.length} messages_`,
    ''
  );

  for (const msg of recentMessages) {
    const role = msg.role === 'user' ? '**User:**' : '**Assistant:**';
    lines.push(role);
    // Truncate very long messages in context
    lines.push(truncate(msg.content, 2000));
    lines.push('');
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }],
  };
}

async function handleSearchAndSummarize(args: {
  query: string;
  sessionLimit?: number;
  model?: 'haiku' | 'sonnet' | 'opus';
}) {
  const { query, sessionLimit = 3, model = 'haiku' } = args;

  // Check if Claude CLI is available
  if (!isClaudeCliAvailable()) {
    return {
      content: [
        {
          type: 'text',
          text: 'Claude CLI not found. This tool requires Claude Code CLI to be installed.',
        },
      ],
      isError: true,
    };
  }

  // Initialize embeddings if needed
  if (!isReady()) {
    try {
      await initializeEmbeddings();
    } catch {
      return {
        content: [
          {
            type: 'text',
            text: 'Embedding model not available. Please run `cmem setup` first.',
          },
        ],
        isError: true,
      };
    }
  }

  // Semantic search for relevant sessions
  const queryEmbedding = await getEmbedding(query);
  const sessions = searchSessions(queryEmbedding, sessionLimit);

  if (sessions.length === 0) {
    return {
      content: [
        {
          type: 'text',
          text: `No relevant sessions found for: "${query}"`,
        },
      ],
    };
  }

  // Gather content from matching sessions
  const sessionContents: string[] = [];
  for (const session of sessions) {
    const messages = getSessionMessages(session.id);
    if (messages.length === 0) continue;

    // Format session content
    const sessionText = [
      `## Session: ${session.title}`,
      `Project: ${session.projectPath || 'Unknown'}`,
      `Date: ${session.updatedAt}`,
      '',
      ...messages.slice(-20).map((m) => `**${m.role}:** ${truncate(m.content, 1500)}`),
    ].join('\n');

    sessionContents.push(sessionText);
  }

  if (sessionContents.length === 0) {
    return {
      content: [
        {
          type: 'text',
          text: `Found ${sessions.length} sessions but they appear to be empty.`,
        },
      ],
    };
  }

  // Build prompt for Claude to summarize
  const prompt = `You are analyzing past Claude Code conversation sessions to answer a user's question.

<user_question>
${query}
</user_question>

<past_sessions>
${sessionContents.join('\n\n---\n\n')}
</past_sessions>

Based on the past sessions above, provide a concise and helpful answer to the user's question. Focus on:
1. Directly answering their question with specific details from the conversations
2. Mentioning which session(s) the information came from
3. Highlighting any relevant decisions, code snippets, or conclusions

If the sessions don't contain relevant information to answer the question, say so clearly.

Keep your response concise but complete.`;

  // Spawn Claude CLI to generate the summary
  const response = await runClaudePrompt(prompt, { model });

  if (!response.success) {
    return {
      content: [
        {
          type: 'text',
          text: `Error generating summary: ${response.error || 'Unknown error'}`,
        },
      ],
      isError: true,
    };
  }

  // Format the response with metadata
  const resultLines = [
    response.content,
    '',
    '---',
    `*Analyzed ${sessions.length} session(s) | Model: ${model}${response.durationMs ? ` | ${(response.durationMs / 1000).toFixed(1)}s` : ''}${response.outputTokens ? ` | ${response.outputTokens} tokens` : ''}*`,
  ];

  return {
    content: [{ type: 'text', text: resultLines.join('\n') }],
  };
}

function formatSessionList(
  sessions: Array<{
    id: string;
    title: string;
    summary: string | null;
    messageCount: number;
    updatedAt: string;
    projectPath: string | null;
  }>,
  header: string
): string {
  if (sessions.length === 0) {
    return `${header}\n\nNo sessions found.`;
  }

  const lines: string[] = [header, ''];

  for (const session of sessions) {
    lines.push(`### ${session.title}`);
    lines.push(`- **ID:** \`${session.id.slice(0, 8)}\` (use this to get full session)`);
    lines.push(`- **Messages:** ${session.messageCount}`);
    lines.push(`- **Updated:** ${formatTimeAgo(session.updatedAt)}`);
    if (session.projectPath) {
      lines.push(`- **Project:** ${session.projectPath}`);
    }
    if (session.summary) {
      lines.push(`- **Summary:** ${truncate(session.summary, 150)}`);
    }
    lines.push('');
  }

  return lines.join('\n');
}

// ==================== LESSON HANDLERS ====================

async function handleSearchLessons(args: {
  query: string;
  projectPath?: string;
  limit?: number;
}) {
  const { query, projectPath = process.cwd(), limit = 5 } = args;

  // Initialize embeddings if needed
  if (!isReady()) {
    try {
      await initializeEmbeddings();
    } catch {
      return {
        content: [
          {
            type: 'text',
            text: 'Embedding model not available. Cannot perform semantic search.',
          },
        ],
        isError: true,
      };
    }
  }

  // Semantic search
  const queryEmbedding = await getEmbedding(query);
  const lessons = searchLessonsByEmbedding(queryEmbedding, projectPath, limit);

  if (lessons.length === 0) {
    return {
      content: [
        {
          type: 'text',
          text: `No lessons found for query: "${query}" in project: ${projectPath}`,
        },
      ],
    };
  }

  const lines: string[] = [`# Lessons matching "${query}"`, ''];

  for (const lesson of lessons) {
    lines.push(`### ${lesson.title}`);
    lines.push(`- **ID:** \`${lesson.id.slice(0, 8)}\``);
    lines.push(`- **Category:** ${lesson.category}`);
    lines.push(`- **Confidence:** ${(lesson.confidence * 100).toFixed(0)}%`);
    lines.push(`- **When to apply:** ${lesson.triggerContext}`);
    lines.push('');
    lines.push(`**Insight:** ${lesson.insight}`);
    if (lesson.reasoning) {
      lines.push(`**Reasoning:** ${lesson.reasoning}`);
    }
    lines.push('');
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }],
  };
}

async function handleGetLesson(args: { lessonId: string }) {
  const { lessonId } = args;

  const lesson = getLesson(lessonId);

  if (!lesson) {
    return {
      content: [{ type: 'text', text: `Lesson not found: ${lessonId}` }],
      isError: true,
    };
  }

  const lines: string[] = [
    `# ${lesson.title}`,
    '',
    `**ID:** ${lesson.id}`,
    `**Category:** ${lesson.category}`,
    `**Project:** ${lesson.projectPath}`,
    `**Confidence:** ${(lesson.confidence * 100).toFixed(0)}%`,
    `**Times Applied:** ${lesson.timesApplied}`,
    `**Times Validated:** ${lesson.timesValidated}`,
    `**Times Rejected:** ${lesson.timesRejected}`,
    `**Archived:** ${lesson.archived ? 'Yes' : 'No'}`,
    `**Created:** ${lesson.createdAt}`,
    `**Updated:** ${lesson.updatedAt}`,
    '',
    '## When to Apply',
    lesson.triggerContext,
    '',
    '## Insight',
    lesson.insight,
  ];

  if (lesson.reasoning) {
    lines.push('', '## Reasoning', lesson.reasoning);
  }

  if (lesson.sourceSessionId) {
    lines.push('', `**Source Session:** ${lesson.sourceSessionId}`);
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }],
  };
}

async function handleSaveLesson(args: {
  projectPath: string;
  category: LessonCategory;
  title: string;
  triggerContext: string;
  insight: string;
  reasoning?: string;
}) {
  const input: CreateLessonInput = {
    projectPath: args.projectPath,
    category: args.category,
    title: args.title,
    triggerContext: args.triggerContext,
    insight: args.insight,
    reasoning: args.reasoning,
    sourceType: 'manual',
    confidence: 0.6, // Manual lessons start with moderate confidence
  };

  try {
    const lesson = await lessonManager.create(input);

    return {
      content: [
        {
          type: 'text',
          text: `Lesson saved successfully!\n\n**ID:** ${lesson.id}\n**Title:** ${lesson.title}`,
        },
      ],
    };
  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Failed to save lesson: ${String(error)}`,
        },
      ],
      isError: true,
    };
  }
}

async function handleValidateLesson(args: { lessonId: string; comment?: string }) {
  const { lessonId, comment } = args;

  const lesson = getLesson(lessonId);
  if (!lesson) {
    return {
      content: [{ type: 'text', text: `Lesson not found: ${lessonId}` }],
      isError: true,
    };
  }

  lessonManager.recordValidation(lessonId, undefined, comment);

  const updated = getLesson(lessonId);

  return {
    content: [
      {
        type: 'text',
        text: `Lesson validated: "${lesson.title}"\nNew confidence: ${((updated?.confidence ?? 0) * 100).toFixed(0)}%`,
      },
    ],
  };
}

async function handleRejectLesson(args: { lessonId: string; comment?: string }) {
  const { lessonId, comment } = args;

  const lesson = getLesson(lessonId);
  if (!lesson) {
    return {
      content: [{ type: 'text', text: `Lesson not found: ${lessonId}` }],
      isError: true,
    };
  }

  lessonManager.recordRejection(lessonId, undefined, comment);

  const updated = getLesson(lessonId);

  let message = `Lesson rejected: "${lesson.title}"`;
  if (updated?.archived) {
    message += '\nLesson has been auto-archived due to low confidence.';
  } else if (updated) {
    message += `\nNew confidence: ${(updated.confidence * 100).toFixed(0)}%`;
  }

  return {
    content: [{ type: 'text', text: message }],
  };
}

async function handleListLessons(args: {
  projectPath: string;
  category?: LessonCategory;
  includeArchived?: boolean;
  limit?: number;
}) {
  const { projectPath, category, includeArchived = false, limit = 20 } = args;

  const lessons = getLessonsByProject(projectPath, {
    category,
    archived: includeArchived ? undefined : false,
    limit,
  });

  if (lessons.length === 0) {
    return {
      content: [
        {
          type: 'text',
          text: `No lessons found for project: ${projectPath}`,
        },
      ],
    };
  }

  const stats = getLessonStats();

  const lines: string[] = [
    `# Lessons for ${projectPath}`,
    '',
    `**Total:** ${lessons.length} | **Active:** ${stats.activeLessons} | **Archived:** ${stats.archivedLessons}`,
    '',
  ];

  for (const lesson of lessons) {
    const archived = lesson.archived ? ' [ARCHIVED]' : '';
    lines.push(`### ${lesson.title}${archived}`);
    lines.push(`- **ID:** \`${lesson.id.slice(0, 8)}\``);
    lines.push(`- **Category:** ${lesson.category}`);
    lines.push(`- **Confidence:** ${(lesson.confidence * 100).toFixed(0)}%`);
    lines.push(`- **Applied:** ${lesson.timesApplied} | **Validated:** ${lesson.timesValidated} | **Rejected:** ${lesson.timesRejected}`);
    lines.push(`- **Insight:** ${truncate(lesson.insight, 100)}`);
    lines.push('');
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }],
  };
}

/**
 * Start the MCP server
 */
export async function startMcpServer(): Promise<void> {
  const server = createMcpServer();
  const transport = new StdioServerTransport();
  await server.connect(transport);
}
