import chalk from 'chalk';
import { createInterface } from 'readline';
import { getPurgePreview, purgeOldSessions, formatBytes, getTotalStorageSize, getDatabaseSize, getBackupsDirSize } from '../db/maintenance.js';
import { DEFAULT_PURGE_DAYS } from '../utils/config.js';

interface PurgeOptions {
  days?: string;
  dryRun?: boolean;
  force?: boolean;
}

export async function purgeCommand(options: PurgeOptions): Promise<void> {
  const days = options.days ? parseInt(options.days, 10) : DEFAULT_PURGE_DAYS;

  if (isNaN(days) || days < 1) {
    console.log(chalk.red('Invalid days value. Must be a positive number.'));
    return;
  }

  const preview = getPurgePreview(days);

  if (preview.sessionsToDelete === 0) {
    console.log(chalk.green('No sessions eligible for purge.'));
    console.log(chalk.dim('(Sessions must be older than ' + days + ' days and not starred)'));
    return;
  }

  // Show preview
  console.log(chalk.bold('\nPurge Preview:'));
  console.log(chalk.dim('─'.repeat(50)));
  console.log(`  Database size: ${chalk.cyan(formatBytes(getDatabaseSize()))}`);
  console.log(`  Backups size:  ${chalk.cyan(formatBytes(getBackupsDirSize()))}`);
  console.log(`  Total storage: ${chalk.cyan(formatBytes(getTotalStorageSize()))}`);
  console.log();
  console.log(`  Sessions to delete: ${chalk.yellow(preview.sessionsToDelete.toString())}`);
  console.log(`  Messages involved:  ${chalk.yellow(preview.messagesInvolved.toString())}`);
  if (preview.backupFilesToDelete > 0) {
    console.log(`  Backup files:       ${chalk.yellow(preview.backupFilesToDelete.toString())} (~${formatBytes(preview.backupBytesToFree)})`);
  }
  console.log(`  Date range: ${chalk.dim(preview.oldestSessionDate)} to ${chalk.dim(preview.newestSessionDate)}`);
  console.log(chalk.dim('  (Starred sessions will be preserved)'));
  console.log(chalk.dim('─'.repeat(50)));

  if (options.dryRun) {
    console.log(chalk.cyan('\n[Dry run] No changes made.'));
    return;
  }

  // Confirm unless --force is specified
  if (!options.force) {
    const confirmed = await confirm(
      chalk.red(`\nDelete ${preview.sessionsToDelete} sessions? This cannot be undone. [y/N] `)
    );

    if (!confirmed) {
      console.log(chalk.dim('Cancelled.'));
      return;
    }
  }

  // Perform purge
  const result = purgeOldSessions(days);
  console.log(chalk.green(`\nPurged ${result.sessionsDeleted} session${result.sessionsDeleted !== 1 ? 's' : ''}.`));
  if (result.backupsDeleted > 0) {
    console.log(chalk.green(`Deleted ${result.backupsDeleted} backup file${result.backupsDeleted !== 1 ? 's' : ''}.`));
  }
  console.log(`New storage size: ${chalk.cyan(formatBytes(getTotalStorageSize()))}`);
}

function confirm(prompt: string): Promise<boolean> {
  const rl = createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  return new Promise(resolve => {
    rl.question(prompt, answer => {
      rl.close();
      resolve(answer.toLowerCase() === 'y' || answer.toLowerCase() === 'yes');
    });
  });
}
