import chalk from 'chalk';
import { processSynthesisQueue, getQueueStatus } from '../learning/processQueue.js';
import { getLessonStats, cleanupOldInjections } from '../db/lessons.js';

interface SynthesizeOptions {
  limit?: string;
  status?: boolean;
}

export async function synthesizeCommand(options: SynthesizeOptions): Promise<void> {
  // Get current status
  const status = getQueueStatus();
  const lessonStats = getLessonStats();

  // If status only, just display and exit
  if (options.status) {
    console.log(chalk.cyan('Synthesis Queue Status\n'));
    console.log(`  Pending:    ${chalk.yellow(status.pending)}`);
    console.log(`  Processing: ${chalk.blue(status.processing)}`);
    console.log(`  Completed:  ${chalk.green(status.completed)}`);
    console.log(`  Failed:     ${chalk.red(status.failed)}`);
    console.log('');
    console.log(chalk.cyan('Lesson Statistics\n'));
    console.log(`  Total:    ${lessonStats.totalLessons}`);
    console.log(`  Active:   ${lessonStats.activeLessons}`);
    console.log(`  Archived: ${lessonStats.archivedLessons}`);
    console.log(`  Avg Confidence: ${(lessonStats.avgConfidence * 100).toFixed(0)}%`);
    console.log('');
    console.log(chalk.dim('Categories:'));
    for (const [category, count] of Object.entries(lessonStats.byCategory)) {
      if (count > 0) {
        console.log(`    ${category}: ${count}`);
      }
    }
    return;
  }

  // Check if anything to process
  if (status.pending === 0) {
    console.log(chalk.yellow('No sessions pending synthesis.'));
    console.log(chalk.dim(`\nTotal lessons: ${lessonStats.totalLessons}`));
    return;
  }

  const limit = parseInt(options.limit || '5', 10);

  console.log(chalk.cyan('Processing synthesis queue...\n'));
  console.log(`  Queue: ${status.pending} pending`);
  console.log(`  Processing up to ${limit} sessions\n`);

  // Process queue
  const result = await processSynthesisQueue(limit);

  // Report results
  console.log(chalk.cyan('\nResults:\n'));
  console.log(`  Processed:       ${chalk.green(result.processed)}`);
  console.log(`  Lessons created: ${chalk.green(result.lessonsCreated)}`);
  console.log(`  Failed:          ${result.failed > 0 ? chalk.red(result.failed) : '0'}`);

  if (result.errors.length > 0) {
    console.log(chalk.yellow('\nWarnings:'));
    for (const error of result.errors.slice(0, 5)) {
      console.log(chalk.dim(`  - ${error}`));
    }
    if (result.errors.length > 5) {
      console.log(chalk.dim(`  ... and ${result.errors.length - 5} more`));
    }
  }

  // Show updated totals
  const newStats = getLessonStats();
  const newStatus = getQueueStatus();
  console.log('');
  console.log(`Remaining in queue: ${newStatus.pending}`);
  console.log(`Total lessons: ${newStats.totalLessons}`);

  // Cleanup old session injection records (older than 7 days)
  try {
    const cleaned = cleanupOldInjections(7);
    if (cleaned > 0) {
      console.log(chalk.dim(`\nCleaned up ${cleaned} old injection cache records`));
    }
  } catch {
    // Ignore cleanup errors
  }
}
